(window.TZ_CONTENT=window.TZ_CONTENT||{})["rg"]={"taaruf.001": "تحریک کا تعارف", "taaruf.002": "یہ اک غیر سیاسی، فرقہ پرستی تے پاک اصلاحی تحریک سے جو امامِ ربانی مجدد الفِ ثانیؒ اور اپنے مرشدینِ کاملین، شمس الکونین خواجہ محمد عبدالخالق نقشبندی، قادری، سہروردیؒ، شمس العارفین حضرت سائیں عبدالرزاق خالقی نقشبندیؒ اور امام الذاکرین سائیں محمد عظیم اللہ رزاقی نقشبندیؒ کے طریقے پہ لوگاں نے شریعت اور سنت آلے پاسے بلاوے سے۔", "taaruf.003": "اڑے نا لالچ سے، نا شہرت اور کثرت کا شوق، بس اللہ کی رضا اور دل اور نفس کی اصلاح سے۔", "taaruf.004": "تحریک کے مقصد", "taaruf.005": "تحریک اتباعِ سنت پاکستان اک غیر سیاسی اور فرقہ پرستی تے پاک اسلامی تحریک سے، جس میں اُمتِ مسلمہ کا ہر بندہ رکن بن سکے سے۔ اس تحریک کے بنیادی مقصد یہ سیں:", "taaruf.006": "آج کے اس فتنیاں آلے دور میں جد بدعات اور خرافات اپنے عروج پہ سیں، اُمتِ مسلمہ میں خوفِ خدا اور عشقِ مصطفیٰ ﷺ پاون خاطر بدعات اور خرافات تے بچن کا، اور شریعتِ مطہرہ اور سنتِ مصطفیٰ ﷺ نے سیکھن سکھان اور ان پہ عمل کرن کا شوق پیدا کرنا۔ اس سلسلے میں گھنے تے گھنا درس و تدریس کا انتظام کرن کے نال نال چالتے پھرتے شریعت و سنت کی تبلیغ کرنا۔", "taaruf.007": "شریعت و سنت اور قرآن کی تعلیم پھیلان خاطر گھنے تے گھنے دینی مدرسے بنانا۔", "taaruf.008": "خدمتِ خلق کا جذبہ پیدا کرن اور یتیم پروری نے بڑھاون خاطر یتیم خانے بنانا۔", "taaruf.009": "خاص کر کے نوجوان نسل نے بے حیائی اور برائی تے بچا کے پنج وقتی نماز باجماعت خاطر مسجد میں لیانا۔", "taaruf.010": "روز کے کماں کے علاوہ بیاہ شادی اور دوجے خوشی غمی کے موقعیاں پہ ہون آلی بدعات نے مکان اور شریعت و سنت نے پھیلان خاطر گھنی تے گھنی ذکرِ خدا اور ذکرِ مصطفیٰ ﷺ کی محفلاں کروانا۔", "taaruf.011": "قرآن و سنت کی روشنی میں اولیائے کاملین کی اصلی تعلیمات نے پھیلانا، اور جعلی، شعبدہ باز، جدی پشتی پیراں کی من گھڑت تعلیمات نے جڑ تے مکا کے اج کے زمانے میں تصوف کے بگڑے ہوئے چہرے نے تازگی دینا۔", "taaruf.012": "کریم آقا ﷺ تے کامل محبت پاون خاطر درود و سلام اور ذکر و نعت کی محفلاں نے بڑھانا۔", "taaruf.013": "معاشرے کی اخلاقی برائیاں نے مکانا اور اچھے سلوک اور اخلاقی تعلیمات کا رواج پانا۔", "taaruf.014": "زنانیاں میں فیشن پرستی کی جگہ شرعی پردے اور اپنے خاونداں کی تابعداری کا رجحان پیدا کرنا۔", "taaruf.015": "سارے عالمِ اسلام، خاص کر کے پیارے وطن پاکستان کی محبت اور وفاداری کا جذبہ پیدا کرنا۔", "taaruf.016": "اوّل وقت میں نماز پڑھن نے بڑھانا۔ آج کل فجر اور ظہر کی نمازاں مسجداں میں گھنی دیر تے پڑھی جاویں سیں جو نماز تے غفلت سے، حالانکہ حنفی اوقات کے مطابق وقت گھنا پہلاں ہو جاوے سے۔", "taaruf.017": "ناموسِ رسالت اور ختمِ نبوت کی حفاظت کرنا اور یہود و ہنود اور قادیانیاں کی سازشاں نے ننگا کرنا۔", "taaruf.018": "اتباعِ رسول ﷺ", "taaruf.019": "قرآنِ کریم کی روشنی میں", "taaruf.020": "سورۂ آلِ عمران میں اللہ تعالیٰ فرماوے سے: <span class=\"kk-ar\" style=\"display:block\">قُلْ اِنْ كُنْتُمْ تُحِبُّوْنَ اللّٰهَ فَاتَّبِعُوْنِيْ يُحْبِبْكُمُ اللّٰهُ وَيَغْفِرْ لَكُمْ ذُنُوْبَكُمْ</span>(فرما دیو! جے تم اللہ تے محبت کرو ہو تو میری اتباع کرو، اللہ تم تے محبت کرے گا اور تمہارے سارے گناہ معاف فرما دیوے گا)۔ آپ ﷺ خدا تعالیٰ کے محبوب سیں، محب اُس بندے نے بھی اپنا محبوب بنا لیوے سے جس میں اپنے محبوب کی عادتاں اور خصلتاں دیکھے سے۔ اس خاطر آپ ﷺ کی تابعداری میں کوشش کرنا مقامِ محبوبیت تک لے جان آلا اور گناہاں نے مٹان آلا سے۔ ہر دانا اور عقلمند پہ واجب سے کہ ظاہر اور باطن میں آپ ﷺ کی کمال تابعداری میں کوشش کرے۔", "taaruf.021": "سورۃ الاحزاب میں فرمایا: <span class=\"kk-ar\" style=\"display:block\">لَقَدْ كَانَ لَكُمْ فِيْ رَسُوْلِ اللّٰهِ اُسْوَةٌ حَسَنَةٌ لِّمَنْ كَانَ يَرْجُوا اللّٰهَ وَالْيَوْمَ الْاٰخِرَ وَذَكَرَ اللّٰهَ كَثِيْرًا</span>(بیشک تمہارے خاطر رسول اللہ ﷺ سب تے اچھا نمونہ سیں اُس خاطر جو اللہ اور آخرت کے دن کی امید رکھے سے اور اللہ کا ذکر گھنا کرے سے)۔ اس خاطر جو اللہ آلے پاسے رجوع کرے اور آخرت کی تیاری کرنا چاہوے اور گھنا ذکرِ الٰہی بھی کرن آلا ہووے تو اُسے چاہیے کہ زندگی کے ہر ہر پہلو میں نبی کریم ﷺ کے روشن طریقے کی پیروی کرے۔", "taaruf.022": "سورۃ النساء میں فرمایا: <span class=\"kk-ar\" style=\"display:block\">مَنْ يُّطِعِ الرَّسُوْلَ فَقَدْ اَطَاعَ اللّٰهَ</span>(جس نے رسول ﷺ کی اطاعت کری اُس نے حق تعالیٰ کی اطاعت کری)۔ پتہ لگا کہ اللہ تعالیٰ نے اپنی اطاعت اپنے حبیب ﷺ کی اطاعت میں چھپا کے رکھی سے۔ اطاعتِ رسول ہی اطاعتِ الٰہی سے اور ذکرِ رسول ﷺ عین ذکرِ خدا سے۔ اب جو رسول اللہ ﷺ کی اطاعت نے اللہ تعالیٰ کی اطاعت تے الگ جانے وہ قرآن کا منکر سے۔", "taaruf.023": "<b>اطاعتِ رسول ﷺ اللہ کے مقرب بندیاں کی رفاقت اور ساتھ کا ذریعہ:</b> سورۃ النساء میں فرمانِ الٰہی سے: <span class=\"kk-ar\" style=\"display:block\">وَمَنْ يُّطِعِ اللّٰهَ وَالرَّسُوْلَ فَاُولٰٓئِكَ مَعَ الَّذِيْنَ اَنْعَمَ اللّٰهُ عَلَيْهِمْ مِّنَ النَّبِيّٖنَ وَالصِّدِّيْقِيْنَ وَالشُّهَدَآءِ وَالصّٰلِحِيْنَ ۚ وَحَسُنَ اُولٰٓئِكَ رَفِيْقًا</span>(جس نے اللہ اور اُس کے رسول ﷺ کی اطاعت کری تو یہ لوگ اُن حضرات کے نال ہوں گے جن پہ اللہ تعالیٰ نے انعام فرمایا یعنی انبیاء، صدیقین، شہداء اور صالحین، اور یہ حضرات گھنے اچھے ساتھی سیں)۔", "taaruf.024": "<b>رسول اللہ ﷺ کی اطاعت کے بغیر عمل ضائع ہو جاویں سیں:</b> سورۂ محمد میں ارشادِ الٰہی سے: <span class=\"kk-ar\" style=\"display:block\">يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْٓا اَطِيْعُوا اللّٰهَ وَاَطِيْعُوا الرَّسُوْلَ وَلَا تُبْطِلُوْٓا اَعْمَالَكُمْ</span>(ایمان آلیو! اللہ کی اطاعت کرو اور رسول ﷺ کی اطاعت کرو اور اپنے عملاں نے ضائع مت کرو)۔", "taaruf.025": "<b>اطاعتِ رسول ﷺ رحمتِ خداوندی کا ذریعہ:</b> سورۂ آلِ عمران میں سے: <span class=\"kk-ar\" style=\"display:block\">وَاَطِيْعُوا اللّٰهَ وَالرَّسُوْلَ لَعَلَّكُمْ تُرْحَمُوْنَ</span>(اللہ اور اُس کے رسول ﷺ کی اطاعت کرو تاکہ تم پہ رحم کیا جاوے)۔", "taaruf.026": "<b>اطاعتِ رسول ﷺ دونوں جہاناں کی کامیابی کا سبب:</b> <span class=\"kk-ar\" style=\"display:block\">وَمَنْ يُّطِعِ اللّٰهَ وَرَسُوْلَهٗ فَقَدْ فَازَ فَوْزًا عَظِيْمًا</span>اور جس نے اللہ اور اُس کے رسول ﷺ کی اطاعت کری تو اُس نے گھنی بڑی کامیابی پا لی۔ (سورۃ الاحزاب)", "taaruf.027": "سورۃ النور کی آیت ۵۱ میں کامیاب مومناں کی صفت بیان فرمائی: (مسلماناں کی بات تو یہ سے کہ جد اُنہاں نے کسے مقدمے میں اللہ اور اُس کے رسول ﷺ آلے پاسے بلایا جاوے سے تاکہ اُن کے بیچ فیصلہ فرما دیوے تو وہ کہویں سیں کہ ہم نے سنا اور مان لیا اور یہی لوگ فلاح پان آلے سیں)۔ اگلی آیت میں فرمایا: <span class=\"kk-ar\" style=\"display:block\">وَمَنْ يُّطِعِ اللّٰهَ وَرَسُوْلَهٗ وَيَخْشَ اللّٰهَ وَيَتَّقْهِ فَاُولٰٓئِكَ هُمُ الْفَآئِزُوْنَ</span>(اور جس نے اللہ اور اُس کے رسول ﷺ کی اطاعت کری اور اللہ تے ڈریا اور تقویٰ اختیار کیا تو یہی لوگ کامیاب ہون آلے سیں)۔ اِس آیت کی وضاحت میں حضرت عمرؓ نے فرمایا کہ جو بندہ فرضاں میں اللہ تعالیٰ کی اطاعت اور سنتاں میں رسول اللہ ﷺ کی پیروی کرے سے اور پچھلی ہوئی غلطیاں کی وجہ تے اللہ تعالیٰ تے ڈرے سے اور آن آلی زندگی میں اللہ کی نافرمانی تے بچے سے یہی لوگ کامیاب سیں، اور کامیاب وہ بندہ سے جسے جہنم کی آگ تے بچا کے جنت میں داخل کر دیا گیا۔ (ضیاء القرآن)", "taaruf.028": "سورۃ الانفال میں فرمایا: اے ایمان آلیو! اللہ اور رسول ﷺ کے بلان پہ حاضر ہو جاؤ جد رسول تمہیں اُس چیز خاطر بلاویں جو تمہیں زندگی دیوے گی۔ (۲۴)۔ حضور ﷺ کا بلانا ہی اللہ تعالیٰ کا بلانا سے۔", "taaruf.029": "سورۃ الحشر میں فرمانِ الٰہی سے: اور جو کچھ تمہیں رسول ﷺ عطا فرماویں وہ لے لیو اور جس تے منع فرماویں اُس تے رک جاؤ اور اللہ تے ڈرو۔ (۷)۔ اِس آیتِ کریمہ تے پتہ لگا کہ آپ ﷺ کی اطاعت یعنی احکامِ الٰہی پہ عمل کرنا اور برے کماں تے رکنا واجب سے، اللہ اُسے سخت عذاب دیوے گا جو آپ ﷺ کی نافرمانی کرے۔", "taaruf.030": "احادیثِ مبارکہ کی روشنی میں", "taaruf.031": "<span class=\"kk-ar\" style=\"display:block\">خَيْرُ الْهُدٰى هُدٰى مُحَمَّدٍ ﷺ</span>سب تے اچھا راستہ حضرت محمد ﷺ کا راستہ سے۔ (بخاری)", "taaruf.032": "فرمانِ مصطفیٰ ﷺ سے کہ جو بندہ میری سنت تے منہ موڑے یا جان بوجھ کے چھوڑ دیوے تو وہ ہم میں تے نہیں اور نا وہ قیامت کے دن شفاعت کا حقدار ہووے گا۔ اور جس نے میری سنت تے محبت کری اُس نے مجھ تے محبت کری، اور جس نے مجھ تے محبت کری وہ جنت میں میرے نال ہووے گا۔ (ترمذی)", "taaruf.033": "میری اُمت کا ہر بندہ جنت میں جاوے گا پر جس نے میرا انکار کیا (وہ جنت میں نہیں جاوے گا)۔ پوچھن پہ فرمایا: جس نے میری نافرمانی کری اُس نے میرا انکار کیا۔ اِس پہ قرآن گواہ سے: اُس دن ظالم بندہ اپنے ہاتھاں نے چبا چبا کے کہوے گا کہ ہائے کاش! میں نے رسول اللہ ﷺ کی راہ اپنائی ہوتی، ہائے افسوس! کاش میں نے فلانے نے دوست نا بنایا ہوتا۔ (سورۃ الفرقان: ۲۷)", "taaruf.034": "حضور نبی کریم ﷺ نے دعا فرمائی کہ میرے نائباں پہ اللہ تعالیٰ کی رحمت ہووے۔ کسے نے عرض کری کہ آپ ﷺ کے نائب کون سیں؟ فرمایا: جو میری سنت تے محبت کریں سیں اور اُسے اللہ تعالیٰ کے بندیاں نے سکھاویں سیں۔ (جامع بیان العلم و فضلہ)", "taaruf.035": "اپنے وصال تے پہلاں ارشاد فرمایا: تم میں دو چیزاں چھوڑ کے جا رہا ہوں، جد تک اِن دونوں پہ مضبوطی تے قائم رہو گے گمراہ نہیں ہوو گے، اک کتاب اللہ اور دوجی سنتِ رسول اللہ ﷺ۔ (بخاری، کتاب الاحکام)", "taaruf.036": "بزرگاں کے اقوال کی روشنی میں", "taaruf.037": "<b>ثانی اثنین سیدنا صدیقِ اکبر رضی اللہ عنہ:</b> پہلے خلیفہ بنن کے بعد اپنے تاریخی خطبے میں فرمایا کہ جد تک میں اللہ تعالیٰ اور اُس کے رسول ﷺ کی اطاعت کراں، تم میری اطاعت کریو اور جے میں اُن کے خلاف کراں تو میرا ساتھ چھوڑ دیو۔ آپؓ نے اتباعِ رسول ﷺ کا کمال شوق تھا۔ اِس کا اندازہ اُس گل بات تے لگ سکے سے جو آپؓ کے وصالِ مبارک تے چند گھنٹے پہلاں آپ رضی اللہ عنہ اور آپ کی پیاری صاحبزادی اُم المومنین سیدہ عائشہ صدیقہؓ کے بیچ ہوئی۔ فرمایا: عائشہؓ! تم نے رسولِ خدا ﷺ نے کتنے کپڑیاں میں دفن کیا تھا؟ عرض کری کہ تین سفید کپڑیاں میں جن میں نا قمیص تھی نا عمامہ۔ فرمایا: رسول اللہ ﷺ نے کس دن وفات پائی؟ عرض کری: پیر کے دن۔ فرمایا: آج کون سا دن سے؟ عرض کری: پیر۔ فرمایا: مجھے امید سے کہ میری وفات اِس ویلے اور رات کے بیچ ہووے گی۔ تو اللہ کے فضل تے ایسا ہی ہویا کہ اللہ رب العزت نے وصال کے ویلے بھی آپ رضی اللہ عنہ نے اتباعِ رسول ﷺ کا شرف عطا فرمایا اور پیر کے دن تریسٹھ برس کی عمرِ مبارک میں آپ رضی اللہ عنہ کا وصال ہویا۔ فرمایا کرتے کہ جس کم پہ رسول اللہ ﷺ عمل کیا کرتے تھے میں اُسے کرے بغیر نہیں چھوڑتا، جے میں حضور ﷺ کے حال تے کسے کم نے چھوڑ دیواں تو مجھے ڈر سے کہ سنتِ رسول ﷺ تے ہٹ جاؤں گا۔", "taaruf.038": "<b>سلطان العارفین حضرت بایزید بسطامیؒ:</b> آپ نے اک بندے کے بارے میں پتہ لگا کہ وہ سدا تے راتاں نے قیام کرے سے اور دناں نے روزہ رکھے سے۔ فرمایا: اُس نے مجاہدے تے اپنے اندر فرشتیاں آلی صفتاں پیدا کر لی سیں پر یہ کوئی مقام نہیں اور نا یہ ولایت سے، بلکہ کمالِ ولایت یہ سے کہ اپنے اندر صفاتِ محمدی ﷺ پیدا کرے، یعنی اپنی زندگی کے سارے ویلے اپنا قیام و روزہ اور بولنا کھانا سنتِ مصطفیٰ ﷺ کے مطابق ڈھال لیوے۔ شریعت کا راستہ پلِ صراط تے بھی گھنا باریک اور خطرناک سے اس خاطر کسے بھی حال میں شریعت کی حداں تے باہر قدم نہیں رکھنا چاہیے۔", "taaruf.039": "<b>سید الطائفہ شیخ جنید بغدادیؒ:</b> فرماویں سیں کہ اتباعِ شریعت تو بس وہی کر سکے سے جس کے سجے ہاتھ میں قرآن پاک ہووے اور کھبے ہاتھ میں سنتِ مصطفیٰ ﷺ۔ اِن دونوں دیویاں کی روشنی میں راستہ طے کرے تاکہ نا تو شک کے کھڈیاں میں گرے نا بدعت کے اندھیریاں میں پھنسے۔", "taaruf.040": "<b>غوثِ زماں شیخ ابوالقاسم گرگانیؒ:</b> فرماویں سیں کہ پانی کے اوپر چالنا، ہوا میں اڑنا اور غیب کی باتاں جاننا اور بتانا، اِن میں تے کسے نے بھی کرامت نہیں کہہ سکتے کیونکہ یہ سب کچھ تو شیطان کی مدد تے بھی ہو سکے سے، بلکہ کتنے ہی کاہن سیں جو غیب کی باتاں بتا دیویں سیں۔ بلکہ سب تے بڑی کرامت یہ سے کہ بندہ سر تے پیر تک امرِ الٰہی بن جاوے اور تن من دھن تے شریعت کا تابع ہو جاوے اور اُس کے کسے کم یا حرکت میں احکامِ شریعت کی خلاف ورزی کا شائبہ تک نظر نا آوے۔ جے یہ حال ہووے تو وہ قابلِ اعتبار سے۔ شریعت کی پیروی میں جے تو شیر پہ سواری نا کر سکے تو کوئی گل نہیں کیونکہ غصے اور غضب کے اُس کتے یعنی نفس نے جو تیرے سینے میں موجود سے دبا لینا گھنے شیراں پہ سواری کرن تے کئی درجے افضل سے۔ نفس کے مکر اور فریب تے واقف ہو جانا سب تے بڑی غیب دانی سے۔ حس اور خیال کے دائرے تے باہر ہو جانا پانی پہ چالن اور ہوا میں اڑن تے کچھ گھٹ تو نہیں۔ دنیا کے لالچ اور دنیاوی مشغلیاں تے بے نیاز ہو کے آگے نکل جانا اور اک مشتبہ یعنی شک آلے درہم نے ٹھکرا دینا گھنے بڑے بڑے میداناں نے، جنگلاں نے ٹپ جان اور اک اوکھی گھاٹی نے پار کرن تے گھٹ تو نہیں، کہ حق تعالیٰ نے اِن رکاوٹاں نے اپنے کلامِ پاک میں گھاٹیاں کا ناں دیا سے۔", "taaruf.041": "<b>حضرت داتا گنج بخش ہجویریؒ:</b> روحانی ترقی خاطر اتباعِ شریعت نے لازمی قرار دیتے ہوئے فرماویں سیں کہ شریعت میں پہلا رکن کتاب سے۔ جیسے خدا تعالیٰ فرماوے سے: قرآن پاک میں آیاتِ محکمات سیں کہ وہ اصل کتاب سیں۔ (سورۂ آلِ عمران: ۷)۔ دوجا رکن سنتِ رسول ﷺ سے جس کا ماخذ احادیث سیں۔ جیسے قرآن پاک میں سے: اور جو رسول اللہ ﷺ نے فرمایا سے اُس پہ عمل کرو اور جس بات تے منع فرمایا سے اُس تے بچو۔ (سورۃ الحشر)۔ تیجا رکن اجماعِ اُمت سے کہ رسول اللہ ﷺ نے فرمایا: میری اُمت گمراہی پہ اکٹھی نہیں ہووے، سدا سوادِ اعظم نے اختیار کرو۔ اِس تے تقلید کا جائز ہونا بھی واضح ہو گیا۔ کوئی صوفی شریعت اور حقیقت میں فرق نہیں کر سکتا۔ صوفیانہ تعلیمات پوری طرح احکامِ شریعت کے تابع سیں۔ اس خاطر طریقت اصل میں شریعت ہی نے اپنی زندگی کی گہرائیاں میں پان کا ناں سے۔", "taaruf.042": "<b>غوث الاعظم محی الدین شیخ عبدالقادر جیلانیؒ:</b> فرمایا کہ اندھیرے میں دیوا لے کے داخل ہو اور وہ دیوا کتاب اللہ اور نبی کریم ﷺ کی سنتِ مبارکہ سے۔ کتاب و سنت کے حکماں تے ہرگز باہر نا نکل۔ جے تیرے دل میں کوئی خیال آوے جیسے زنا، سود اور فاسق فاجر لوگاں کے نال میل جول وغیرہ، یا الہام پیدا ہووے تو اُسے کتاب و سنت کی روشنی میں دیکھ، جے تو کتاب و سنت میں اُس کی حرمت پاوے تو اُسے قبول نا کر اور اُس تے الگ ہو جا اور یہ یقین کر لے کہ وہ شیطان مردود کی طرف تے سے۔ بندہ شرع کی حداں کی حفاظت کی وجہ تے اُس غلام جیسا ہو جاوے سے جسے مالک سارے کم سونپ دیوے سے۔ (فتوح الغیب)", "taaruf.043": "<b>شیخ الشیوخ شیخ شہاب الدین عمر سہروردیؒ:</b> سلسلہ سہروردیہ کے بانی، حضرت بہاؤالدین زکریاؒ کے مرشد، کتاب عوارف المعارف میں فرماویں سیں کہ رسولِ اکرم ﷺ نے فرمایا: اُس ذات کی قسم جس کے قبضے میں میری جان سے! اللہ تعالیٰ نے وہی لوگ پیارے سیں جو اُس کے بندیاں میں اللہ کی محبت کا جذبہ جگاویں سیں اور اُنہاں نے اللہ کا محبوب بنان کی کوشش کریں سیں، بلکہ دھرتی پہ ہر بندے کی بھلائی خاطر لگے رہویں سیں۔ اِس حدیث میں مشائخِ کرام کی صفتاں بیان کری گئی سیں۔ شیخ اللہ آلے پاسے دعوت میں پیغمبراں کی نیابت کرتے ہوئے اپنے مرید میں اللہ کی محبت اِس طرح پیدا کرے سے کہ اُسے رسولِ اکرم ﷺ کی اتباع اور پیروی کی راہ پہ لا کے تزکیۂ نفس کی راہ پہ چلاوے سے۔ اس خاطر جو صحیح طریقے تے رسولِ اکرم ﷺ کی اتباع کرے سے تو اللہ بھی اُس تے محبت کرن لگ جاوے سے۔", "taaruf.044": "<b>امام الطریقت خواجۂ خواجگان سید محمد بہاؤالدین نقشبندؒ:</b> ہمارے طریقے کی بنیاد احادیث اور آثار کی پیروی پہ سے اور ہمارا مقصد یہ سے کہ ہمارا سلوک سنتِ رسول ﷺ کی اتباع پہ ہووے اور حق اور باطل میں فرق ہوتا رہوے۔ خاصانِ خدا وہ سیں جو شریعتِ مطہرہ کی پیروی کریں اور اہلِ سنت و الجماعت کے مذہب پہ اپنی زندگی پوری کریں۔ جے ریاضت میں کمر ٹیڑھی ہو کے تمہارا بدن کمان جیسا ہو جاوے اور ریاضت میں بھی کامیاب ہووے پر جد تک اپنا لقمہ اور لباس پاک نا کرے اور شریعتِ رسول ﷺ کی پیروی نا کرے منزلِ مقصود تک نہیں پہنچے گا۔ اس خاطر سارے کماں کا دار و مدار اِسی پہ سے۔ (انیس الطالبین)", "taaruf.045": "<b>امامِ ربانی محبوبِ سبحانی حضرت مجدد الف ثانیؒ:</b> فرماویں سیں کہ شریعت کے تین جز سیں: علم، عمل اور اخلاص۔ جد تک یہ تینوں جز پورے نا ہوویں شریعت حاصل نہیں ہووے۔ اور جد شریعت حاصل ہو گئی تو جانو حق تعالیٰ کی رضا حاصل ہو گئی، جیسے ارشادِ الٰہی سے: (اور اللہ تعالیٰ کی رضا سب تے بڑھ کے سے)۔ اس خاطر ایسا کوئی مقصد باقی نہیں جس نے پاون خاطر شریعت کے سوا کسے اور چیز کی لوڑ پڑے۔ طریقت اور حقیقت جن تے صوفیاء الگ پہچانے جاویں سیں، یہ شریعت کے تیجے جز اخلاص نے پورا کرن میں شریعت کے خادم سیں۔ اس خاطر اِن دونوں نے پورا کرن کا مقصد شریعت نے پورا کرنا سے، نا کہ شریعت کے سوا کوئی اور کم۔ زبان تے جھوٹ نا بولنا شریعت سے اور دل تے جھوٹ کا خیال دور کرنا یعنی سچ کی عادت بغیر تکلیف اور بناوٹ کے حاصل ہو جانا حقیقت یعنی تصوف سے۔ اس خاطر تصوف شریعت نے پورا کرن آلا سے نا کہ اُس کا مخالف۔ وہ علوم و معارف جو صوفیاء نے اِس راہ میں ملیں سیں وہ اصلی مقصد نہیں سیں بلکہ وہم اور خیالات سیں جن تے طریقت کے بالکاں کی تربیت کری جاوے سے۔ اِن سب تے گزر کے مقامِ رضا تک پہنچنا چاہیے کیونکہ یہ جذبہ و سلوک کا سب تے اونچا مقام سے۔ بے سمجھ لوگ اِن تجلیات اور مشاہدات نے اصلی مقصد سمجھ کے شریعت کے کمالات تے محروم رہ جاویں سیں۔ ہاں مقامِ اخلاص اور مرتبۂ رضا تک پہنچنا اِن احوال نے طے کرن اور علوم و معارف پاون پہ ٹکا سے۔ اس خاطر یہ احوال و معارف اصل مقصد پاون خاطر اسباب اور وسیلہ سیں۔ شریعت احوال کے تابع نہیں بلکہ باطنی احوال شریعت کے تابع سیں، کیونکہ شریعت قطعی سے، وحی تے ثابت سے اور احوال گمان آلے سیں جو کشف اور الہام تے ثابت ہوویں سیں۔ اس خاطر جس گروہ نے حق تعالیٰ نے آپ ﷺ کی اتباع کی وجہ تے نہایت النہایہ تک پہنچایا سے وہ علم اور عمل میں بال برابر بھی شریعت کا مخالف نہیں ہووے۔ اور علومِ لدنی جو اُن پہ اتریں سیں وہ شریعت کے موافق سیں بلکہ علومِ شرعیہ کی تفصیل سیں۔ ہر وہ کشف جو ظاہرِ شریعت کے خلاف ہووے قبول کرن جوگا نہیں کیونکہ وہ آپ ﷺ کے راستے تے ہٹ کے سے۔ سورۂ یٰسین میں فرمانِ الٰہی سے: (بیشک آپ ﷺ رسولاں میں تے سیں اور صراطِ مستقیم پہ سیں)۔ حیرانی سے کہ کچھ ناقص لوگ اپنے خیالی کشف نے معتبر سمجھیں سیں اور روشن شریعت کی مخالفت اور انکار میں کوشش کریں سیں، حالانکہ حضرت موسیٰ علیہ السلام بھی اپنی کلیمی اور خاص قرب کے باوجود جے دنیا میں ہوتے تو وہ بھی اِسی شریعتِ مطہرہ کی پیروی کرتے۔", "taaruf.046": "سورۃ البقرہ میں سے: جو ایمان آلے سیں اُن کی محبت اللہ خاطر گھنی سخت سے۔ (۱۶۵)۔ اس خاطر شرعی حکم بجا لان کی توفیق اللہ کی محبت کا نتیجہ سے اور باطن کی جمعیت کا حاصل ہونا اِسی محبت کا پھل سے۔ جے سارے جہان جتنی ظلمتاں اور کدورتاں باطن میں ڈال دیویں اور اِس محبت نے قائم رکھیں تو کوئی غم نہیں کرنا چاہیے، اور جے سارے پہاڑاں کے برابر انوار اور کیفیات باطن میں ودھا دیویں پر اِس محبت میں بال برابر کمی کر دیویں تو اِسے خرابی کے سوا کچھ نہیں جاننا چاہیے۔ سچے اور جھوٹے کا فرق شریعت پہ ٹکے رہن یا نا ٹکے رہن تے پتہ لگے سے۔ جو بندہ سچا سے وہ سکر، مستی اور بے خودی کے باوجود بال برابر بھی شرع کے خلاف نہیں کرتا۔ مولانا رومؒ استغراق میں رہتے پر نماز کے ویلے ہوش میں آ جاتے۔", "taaruf.047": "رسول اللہ ﷺ نے فرمایا: تم میں تے کوئی مومن نہیں ہووے گا جد تک اُس کی خواہش اُس امر کے تابع نا ہو جاوے جو میں لیایا ہوں۔ اس خاطر شرعی تکلیفاں میں حکمت یہی سے کہ نفسِ امارہ خراب اور عاجز ہووے۔ جتنا شریعت کے موافق عمل کیا جاوے اُتنی ہی نفس کی خواہشاں گھٹ ہو جاویں سیں۔ یہی وجہ سے کہ شرعی حکماں میں تے اک حکم بجا لانا نفس کی خواہشاں دور کرن میں اُن ہزار سالہ ریاضتاں اور مجاہدیاں تے جو اپنے کول تے کرے جاویں کئی درجے اچھا سے، بلکہ ایسی ریاضتاں اور مجاہدے جو شرع کے موافق نا ہوویں وہ نفس کی خواہشاں نے مدد اور زور دین آلے سیں۔ برہمناں اور جوگیاں نے محنت مجاہدیاں تے نفس نے زور دین اور پالن کے سوا کچھ فائدہ نہیں ہویا۔ جیسے نمازِ فجر کی دو رکعتاں جماعت کے نال پڑھنا جو سنتاں میں تے اک سنت سے، ساری رات قیام کر کے نمازِ فجر بغیر جماعت پڑھن تے کئی درجے اچھا سے، اور شریعت کے حکم تے عید الفطر کے دن کا کھانا اپنی مرضی تے کئی سال روزے رکھن تے اچھا سے، اور نفس نے خراب کرن خاطر زکوٰۃ کے طور پہ اک روپیہ خرچ کرنا اپنی مرضی تے ہزار روپے خرچ کرن تے اچھا سے۔ مطلب جد تک نفس صاف ہو کے سرداری کی پلیدی تے پاک نا ہو جاوے تد تک نجات اوکھی سے اور سدا کی موت تک پہنچن کا خطرہ سے۔", "taaruf.048": "پسندیدہ پیروی کا اک ذرہ ساری دنیاوی لذتاں اور آخرت کی نعمتاں تے کئی درجے اچھا سے۔ بزرگی سنت کی تابعداری پہ اور بڑائی شریعت کی بجا آوری پہ ٹکی سے۔ جو کچھ شریعت کے خلاف سے وہ مردود سے۔ جس حقیقت نے شریعت نے رد کر دیا وہ زندیقہ سے۔ شریعت نے اپنی جگہ قائم رکھ کے حقیقت نے ڈھونڈنا بہادراں کا کم سے۔ حضور ﷺ کے دین کی حقیقت کی تصدیق کرن کے بعد تھوڑا سا عمل بجا لانا بھی گھنے عمل کے برابر سے۔ اصحابِ کہف نے اتنا بڑا درجہ بس اک ہی نیکی کی وجہ تے پایا اور وہ نورِ ایمانی کے نال خدا تعالیٰ کے دشمناں کے غلبے کے ویلے ہجرت کر جانا تھا، کیونکہ دشمناں کے غلبے کے ویلے جے تھوڑی سی بھی کوشش کریں تو وہ اِتنی نمایاں اور قابلِ اعتبار ہووے سے کہ امن کے دناں میں اِس تے کئی گنا عمل بھی اُس اعتبار نے نہیں پہنچ سکتا۔ جے ظاہری ہجرت نا ہو سکے تو باطنی ہجرت نے سامنے رکھتے ہوئے مخلوق کے بیچ رہتے ہوئے اُن تے الگ رہنا چاہیے۔ محشر کے دن شریعت کے بارے میں پوچھیں گے نا کہ تصوف کے بارے میں۔ جنت میں جانا اور دوزخ تے بچنا شریعت کے حکم بجا لان پہ ٹکا سے۔ انبیاء کرام کے آن کا مقصد شریعت کے حکم لوگاں تک پہنچانا ہی سے۔ اس خاطر سب تے بڑی بھاری نیکی یہی سے کہ شرع نے رواج دین اور اِس کے حکماں میں تے کسے حکم نے زندہ کرن میں کوشش کری جاوے، خاص کر ایسے زمانے میں جد اسلام کے نشان بالکل مٹ گئے ہوویں۔ اور جس بندے کے نال گھنے لوگاں کی نجات جڑی ہووے وہ اُس بندے تے اچھا سے جو بس اپنی نجات کے خیال میں سے۔", "taaruf.049": "ارشادِ الٰہی سے: (بیشک یہ میرا سیدھا راستہ سے تم اِس پہ چالو اور دوجے راستیاں پہ نا چالو)۔ رسول اللہ ﷺ نے فرمایا: مجھے میرے رب نے ادب سکھایا اور میری تعلیم و تادیب اچھی طرح کری۔ اس خاطر جے طریقت اور حقیقت کی راہ پہ چالن آلیاں تے راہ کے بیچ ایسے کم ہو جاویں جو دیکھن میں شریعت کے خلاف ہوویں تو وہ غلبۂ حال یعنی مستی کی وجہ تے سیں اور اِس مقام تے گزر کے ہوش میں آن پہ وہ مخالفت مک جاوے سے۔ محمدی المشرب بزرگ شرع اور سنت کی دولت تے مشرف سیں اور ولایتِ خاصۂ محمدی ﷺ اُن کا حصہ سے۔ فنائے اتم اور بقائے اکمل انہی کی شان سے۔ اور اِس کا مخالف چاہے اولیاء میں تے ہووے اور اُسے کشف ہوتا ہووے تو اُس کا اِس ولایت میں حصہ نہیں سے اور وہ پچھلے پیغمبراں میں تے کسے پیغمبر کے قدم پہ سے اور اُس کے علوم اُسی نبی کی شریعت کے موافق سیں۔ شریعتِ محمدی ﷺ دوجی شریعتاں کا نچوڑ سے۔ شریعت اور سنت کی اتباع کے بغیر اِس منزل تک پہنچنا ناممکن سے۔ اس خاطر اُس بندے نے مبارک ہووے جسے اِس بھاری نعمت کا شرف ملیا اور افسوس سے اُس بندے پہ جو اِس اعلیٰ نعمت تے محروم رہیا۔", "taaruf.050": "آپ ﷺ کی ظاہری میراث کا شکر یہ سے کہ باطنی میراث تے سجیا جاوے، اور باطنی میراث تے سجنا آپ ﷺ کی پوری پیروی کے بغیر ناممکن سے۔ اور آپ ﷺ کی کمال محبت کی نشانی یہ سے کہ حضور ﷺ کے دشمناں تے بغض رکھیں اور شریعت کے مخالفاں تے دشمنی ظاہر کریں۔ محبت میں چاپلوسی جائز نہیں کیونکہ محب اپنے محبوب کا دیوانہ ہووے سے اور دو مخالف محبتاں اکٹھی نہیں ہو سکتیں۔ اس خاطر لازم سے کہ اپنی ساری ہمت شریعت کے حکم بجا لان، اہلِ شریعت علماء اور اولیاء کی تعظیم کرن اور بدعتیاں نے خوار رکھن میں لاویں۔ جس نے کسے بدعتی کی تعظیم کری جانو اُس نے اسلام ڈھان میں اُس کی مدد کری۔ حق تعالیٰ اپنے نبی ﷺ کے طفیل ہمارے ظاہر اور باطن نے سنتِ رسول ﷺ کی پیروی تے سجا سنوار دیوے۔ (مکتوباتِ امامِ ربانی مجدد الف ثانیؒ)", "taaruf.051": "ہماری گزارشاں", "taaruf.052": "وطن کی محبت کا جذبہ", "taaruf.053": "حضور نبی کریم رؤف الرحیم ﷺ نے فرمایا: وطن کی محبت ایمان تے سے۔ (الحدیث)", "taaruf.054": "اس خاطر ہمیں چاہیے کہ دینِ اسلام کی سربلندی اور اپنے پیارے وطن پاکستان کی مضبوطی خاطر رات دن کوشش میں لگے رہواں۔ نال ہی اپنے بالکاں کے دلاں میں خوفِ خدا اور عشقِ مصطفیٰ ﷺ کے نال نال وطن کی محبت کا جذبہ بھی پیدا کراں۔ اِس کا سب تے اچھا طریقہ یہ سے کہ جشنِ آزادی کے موقعے پہ بھی اللہ تعالیٰ اور نبی کریم ﷺ کے ذکر کے نال اپنے بزرگاں کی سیرتاں بھی بیان کری جاویں۔ نال ہی جو بندہ جس محکمے میں اپنے فرض نبھاوے سے وہ سچائی اور دیانتداری نے اپنا شعار بناوے، اِتھوں تک کہ گھر میں رہن آلے زنانیاں اور مرد بھی اپنی ذمہ داریاں اچھے طریقے تے نبھاویں۔ اپنے معاشرے نے بہتر بنان خاطر اپنے پڑوسیاں اور نیڑے کے مسکیناں اور فقیراں کا خیال رکھو، آپس میں پیار محبت، اتفاق، اتحاد اور اچھے سلوک تے زندگی گزارو۔ اک اچھا مسلمان ہی اچھا انسان اور اک اچھا پاکستانی ہو سکے سے۔", "taaruf.055": "بے پردگی اور موبائل فوناں کا غلط استعمال اور اِن کی روک تھام", "taaruf.056": "سورۃ النور میں فرمانِ الٰہی سے: اور آپ (ﷺ) مسلمان زنانیاں تے فرما دیو کہ وہ اپنی نگاہاں نیچی رکھیں اور اپنی عفت کی حفاظت کریں اور اپنا بناؤ سنگھار ظاہر نا کریں۔ (۳۱)۔ اور فرمایا: اپنے گھراں میں سکون تے ٹکی رہو اور پرانی جاہلیت آلی بے پردگی جیسی نا رہو۔ (سورۃ الاحزاب)۔ اور فرمایا: خیمیاں کے اندر پردے آلی حوراں سیں۔ (سورۃ الرحمٰن: ۷۲)۔ جنت میں حوراں بھی پردہ کریں گی جڑے برائی کا کوئی ڈر بھی نہیں ہووے گا۔ اصل میں پردہ تو زنانی کی حیا اور سوہنپ سے۔", "taaruf.057": "آج اِس فتنیاں آلے دور میں جد بے پردگی اور بے حیائی عروج پہ سے ہمیں اپنی پاک بیٹیاں کی عفت کی حفاظت خاطر مل کے بے پردگی کی اِس بری رسم نے مکانا ہووے گا، اور اپنی بہو بیٹیاں نے شرعی پردہ کرن کی ترغیب دینی ہووے گی۔ آج کی روشن خیال زنانیاں کہویں سیں کہ پردہ تو نظر کا ہووے سے۔ جد صحابیات نے کریم آقا ﷺ تے پردہ کیا اور اللہ تعالیٰ نے اپنے پاک کلام میں ہر غیر محرم تے پردہ کرن کا حکم فرما دیا تو آج کی اِس روشن خیالی کی کیا حیثیت رہ جاوے سے۔", "taaruf.058": "اِس کے علاوہ! ہمیں اپنے بالکاں نے جتنا ہو سکے موبائل فوناں کے غلط استعمال تے بھی بچانا ہووے گا۔ آج وہی دور آ گیا سے جس کے بارے میں آپ ﷺ نے فرمایا تھا کہ فتنے گھراں کے دروازے توڑ کے اندر وڑ جاویں گے۔ موبائل فون اور ٹی وی ہی وہ فتنہ سیں جن کے ذریعے گھر بیٹھے بالکاں تک بے حیائی اور برائی کی پہنچ ہو گئی سے۔ آج واٹس ایپ سٹیٹس اور سوشل میڈیا پہ ناچ گانے اور کھیل تماشے کے سوا کچھ نظر نہیں آتا۔ خدا کے واسطے! اپنے آپ نے اور اپنے گھر آلیاں نے اُس آگ تے بچاؤ جس کا ایندھن بندے اور پتھر سیں۔", "taaruf.059": "آپ اِس نیک کم میں ہمارے مددگار کس طرح بن سکو ہو", "taaruf.060": "جے آپ ہماری اِس تحریک کے مقصداں تے متفق ہو تو ہمارے مقرر کرے ہوئے کارکناں تے رابطہ کر کے رکنیت فارم اور ڈاک لفافہ بالکل مفت لے کے اِس تحریک کی ممبرشپ لے سکو ہو۔", "taaruf.061": "جے آپ باقاعدہ ممبر نہیں بننا چاہتے تو اِس تحریک نے پھیلان خاطر اِس کتابچے میں لکھی گزارشاں پہ جتنی بھی ہو سکے اکیلے یا مل کے کوشش کر کے ہمارا ساتھ دیو۔", "taaruf.062": "ماخذ: کتابچہ «تحریک اتباعِ سنت پاکستان کا تعارف اور اس کے مقاصد»", "baani.001": "بانی اور قائد کا تعارف", "baani.002": "تحریک اتباعِ سنت پاکستان کے بانی", "baani.004": "شروع کے حالات اور تعلیم", "baani.005": "بانی و قائد تحریک اتباعِ سنت پاکستان، پیرِ طریقت کرامت علی بن محمد الیاس رزاقی کا تعلق گوٹھ محمد ابڑو، صوبہ سندھ تے سے۔ نسب کے حساب تے آپ راجپوت قوم تے سیں۔ شروع کی تعلیم کے بعد 1983-84ء میں ٹنڈو آدم نیو علی گڑھ کالج تے بی کام کری، اور نوکری کے دوران ایم اے اکنامکس کے بعد ایل ایل بی کری۔", "baani.006": "نوکری", "baani.007": "1985ء میں آپ پاکستان پوسٹ میں سینئر کلرک بھرتی ہوئے۔ 2013ء میں اسسٹنٹ سپرنٹنڈنٹ پوسٹل سروسز ہوتے ہوئے، اپنے پیشوا کے حکم تے، ریٹائرمنٹ کے مقرر ویلے تے دس سال پہلاں ریٹائرمنٹ لے کے سلسلہ عالیہ نے پھیلان میں رات دن لگ گئے۔", "baani.008": "بیعت و خلافت", "baani.009": "مذہبی گھرانہ ہون کی وجہ تے شروع تے ہی مذہب آلے پاسے رجحان رہیا اور اپنے بزرگاں کی پیروی میں 1981ء میں سلسلہ عالیہ نقشبندیہ کی عظیم روحانی شخصیت قطبِ عالم حضرت سائیں عبدالرزاقؒ کے دستِ اقدس پہ بیعت ہوئے۔ اُس ویلے کالج میں پڑھتے تھے پر سر پہ سدا ٹوپی رکھتے اور نمازاں کی پابندی کا خاص خیال رکھتے تھے۔ بعد میں آپ نے اپنے پیر و مرشد امام الذاکرین حضور محمد عظیم اللہ رزاقی نقشبندیؒ کی خدمت میں ویلے ویلے گھنا عرصہ گزاریا اور اُن کی فیض آلی صحبت تے فیض پایا۔ نومبر 2006ء میں پیر و مرشد نے آپ نے اپنی خلافت و نیابت تے مشرف فرمایا۔", "baani.010": "دینی خدمتاں", "baani.011": "ہر سال بڑے پیمانے پہ عرسِ مبارک کا انتظام فرماویں سیں۔ پیر بھائیاں تے گھنا تے گھنا رابطہ، وعظ کے ذریعے دین کی تبلیغ اور ذکرِ حبیب ﷺ کی محفلاں کروانا آپ کا طریقہ سے۔ دین اور سلسلے کا پیغام پہنچان خاطر سوشل میڈیا کا اچھا استعمال بھی کریں سیں، اور خلفائے راشدین، اہلِ بیتِ اطہار اور بزرگانِ دین کے وصال کے دناں پہ خاص کر کے آن لائن ٹرانسمیشن کا انتظام کرواویں سیں۔ اِسی مشن کے تحت پاکستان کے مختلف علاقیاں کا سفر بھی کرتے رہویں سیں۔", "baani.012": "آپ کے گاں میں 1972ء تے بنے ہوئے مدرسہ عربیہ خالقیہ رزاقیہ کا انتظام بھی آپ کے کول سے۔ اِس کے علاوہ اپنے گاں میں دانش کدۂ عظیم مرکزِ علم و عرفان بھی بنوایا سے، جس میں مرکزی آفس تحریک اتباعِ سنت پاکستان، لائبریری مجدد الفِ ثانیؒ، زیرِ تعمیر مسجد سیدنا صدیقِ اکبرؓ، اور یتیم اور حقدار بالکاں کی دینی اور دنیاوی تعلیم اور کفالت خاطر مدرسہ اور یتیم خانہ سیں۔ زنانیاں خاطر بھی الگ مدرسے کا انتظام کر رکھیا سے۔ دوجے پیر بھائیاں نے بھی مدرسے بنان کے نال نال ذکر و نعت کی محفلاں کروان کی ترغیب دیویں سیں۔", "baani.013": "تربیت کا طریقہ", "baani.014": "آپ روایتی پیری مریدی تے ہٹ کے اپنے مرشدینِ کاملین کے طریقے کے عین مطابق اپنے مریداں اور ہر آن آلے نے سدا توحید، خوفِ خدا، اللہ پہ توکل اور نبی کریم ﷺ کی محبت اور اتباع کا درس دیویں سیں۔ مدرسے بنان اور دینی تعلیم کے نال نال دنیاوی تعلیم کا بھی خاص انتظام کرواویں سیں۔ مشائخِ عظام کے کشف و کرامات آلی کتاباں کی جگہ، جن میں یقیناً کافی حد تک مبالغہ بھی ہووے سے، اُن اونچے مرتبے آلے مشائخ کی اپنی لکھی کتاباں پڑھن کی ہدایت کریں سیں۔", "baani.015": "تصانیف", "baani.016": "سلسلہ عالیہ میں ہور علمی ذوق پیدا کرن خاطر شریعت اور طریقت پہ دس تے ودھ کتاباں لکھ اور تالیف کر چکے سیں۔ اپنی لکھی ہوئی نعتاں اور منقبتاں کا مجموعہ «حروفِ ثناء» کے ناں تے چھپوا چکے سیں۔ اِس سلسلے نے ہور اگے ودھان خاطر رات دن کوشش میں لگے سیں۔", "baani.017": "تحریر: انجینئر شعیب عالم عظیمی مجددی", "baani.018": "صاحبزادیاں کا تعارف", "baani.019": "صاحبزادہ اویس العظیم عظیمی", "baani.020": "آپ نے سندھ یونیورسٹی تے گریجویشن کری سے اور اِس ویلے سندھ پولیس میں وائرلیس آپریٹر کے طور پہ خدمت کر رہے سیں۔ آپ محفلاں میں شریک ہوویں سیں اور گھنے جوش تے نقابت فرماویں سیں۔", "murshideen.001": "کامل مرشداں کا تعارف", "murshideen.002": "شمس الکونین خواجہ محمد عبدالخالق نقشبندیؒ<span class=\"mk-hint\">تعارف پڑھو ▾</span>", "murshideen.003": "مونسِ بیوگان، دستگیرِ یتامیٰ، فاتحِ قادیانیت<br>شمس الکونین خواجہ محمد عبدالخالق شمس العرفانی نقشبندیؒ", "murshideen.004": "شروع کے حالات", "murshideen.005": "آپ شمس العرفان خواجہ قادر بخشؒ کے شہزادے اور شمس العارفین غوثِ زماں سائیں عبدالرزاقؒ کے پیر و مرشد سیں۔ آپ کا خطاب ابوسعد سے۔ ۷ شوال ۱۲۷۰ھ / ۱۸۵۴ء جمعۃ المبارک کے دن صبحِ صادق کے ویلے جہانخیلاں میں پیدا ہوئے۔ آپ خود فرماویں سیں کہ تین برس کی عمر میں مجھے فرشتیاں میں قطبِ زماں پکاریا جاتا تھا، اور سات سال کی عمر میں نبی کریم ﷺ اور سارے انبیائے کرام نے مجھے اپنی مبارک زباناں چسائیں اور فرمایا کہ ہم نے سارا علم تجھے دے دیا۔ ابھی آپ تقریباً تین سال کے ہی تھے کہ والد بزرگوار شمس العرفان خواجہ قادر بخشؒ نے شہادت پائی۔", "murshideen.006": "علمِ دین کا حصول", "murshideen.007": "علمِ حدیث خاطر سہارنپور میں مولانا احمد علی محدثؒ کی خدمت میں حاضر ہوئے۔ مولانا حسین احمد کانپوریؒ اور پیر مہر علی شاہ گولڑویؒ آپ کے ہم سبق تھے۔ بعد میں دہلی میں مولوی کریم اللہ صاحبؒ اور مولوی سعید احمدؒ تے دینی علوم پہ پوری طرح عبور پایا۔ اللہ تعالیٰ کے فضل و کرم تے آپ علم اور کمال کا اک خزانہ تھے۔ جد کسے طرح کا کوئی مسئلہ آپ کے سامنے رکھیا جاتا تو وضاحت کے نال حوالیاں سمیت اِس طرح بیان فرماتے کہ بڑے بڑے مفتی حیران رہ جاتے۔ خلیفہ مولوی عبدالکریم جسری صاحبؒ اپنی کتاب «خالقیہ» میں لکھیں سیں کہ خواجہ صاحبؒ اِس زمانے میں کامل و اکمل بندے سیں اور مولویاں کی جماعت کے اک بڑے عالم سیں۔", "murshideen.008": "دین کے مبلغ کے طور پہ", "murshideen.009": "آپؒ اکثر کھڑے ہو کے تقریر فرمایا کرتے تھے۔ آپؒ کے شروع کے ملفوظات اور بیانات رشد و ہدایت اور مذہب کی ترغیب اور اسلام کی اشاعت پہ ہوتے تھے۔ جد اللہ تعالیٰ نے آپؒ نے خدمتِ خلق کا حکم فرمایا تو خدمت کے منصب پہ لگ کے مخلوق کی خدمت خاطر کمر کس لی، اور خاص کر کے دو خدمتاں کریں یعنی بیواؤں کا نکاح اور یتیماں اور مسکیناں کی خدمت۔", "murshideen.010": "مرشد کی تلاش میں سیاحت", "murshideen.011": "چھ سال تے پینتیس سال کی عمر تک آپ کا گھنا ویلا سفر میں گزریا۔ اِس تلاش میں سارے ہندوستان، افغانستان، ایران اور عرب وغیرہ کا سفر کیا۔ (خود فرماویں سیں:) پیر پٹھان شاہ سلیمان تونسویؒ، کعبہ شریف میں حاجی امداد اللہ مہاجر مکیؒ اور مدینہ شریف میں صاحبان عبدالغنی و مولانا محمد عمرؒ اور دوجے بزرگاں کی خدمت میں بھی پہنچیا، پر بیعت خاطر سوال اِس شرط پہ کرتا تھا کہ جے آپ میرے سارے بدن تے اللہ، اللہ جاری کرا دیو تو بیعت ہوں گا۔ مشائخ جد یہ سوال سنتے تو ہاتھ کھینچ لیتے تھے۔", "murshideen.012": "سلسلۂ قادریہ میں بیعت و خلافت", "murshideen.013": "فرماویں سیں: الٰہ آباد میں شیخ احمد بخاری قادریؒ کی خدمت میں پہنچیا تو مجھے دیکھتے ہی فرمایا: «برو برو دیگر را بگیر» — جاؤ کوئی اور راستہ دیکھو۔ میں بے تاب ہو کے دوڑ کے قدماں تے لپٹ گیا۔ گھنی شفقت تے میرا سر اٹھا کے سینے تے لایا، اور بیعت فرمان خاطر جد شیخ صاحبؒ نے اپنے مبارک ہاتھ میں میرا ہاتھ لیا اور توجہ دی تو میں بے ہوش ہو گیا۔ اُس ویلے میرے ہر رونگٹے تے اللہ جاری تھا۔ اِسے ہی قرآن مجید میں ذکرِ کثیر فرمایا سے اور اِسے سلطان الاذکار کہویں سیں۔", "murshideen.014": "چھ مہینے کی خدمت کے بعد اک دن سارے درویشاں کے سامنے شیخ صاحب نے خلافت کی دستار میرے سر پہ باندھنی چاہی اور فرمایا کہ کیا یہ اِس قابل سے یا نہیں؟ کسے کے جواب دین تے پہلاں میں نے عرض کری کہ اِس بھاری بوجھ نے اٹھانا تو گھنا اوکھا لگے سے، پر ہاتھ جوڑ کے عرض کروں سوں کہ میری دل کی مراد پوری ہو جاوے۔ فرمایا: وہ کیا سے؟ عرض کری کہ اپنا وجد بخش دیو۔ آپؒ نے یہ سن کے سارے درویشاں تے فرمایا: تم لوگ سدا کہیا کرتے تھے کہ شیخ صاحب نے اِس چھورے تے گھنی محبت سے، اب بتاؤ جو سوال اِس چھورے نے کیا سے کدے تمہارے دل میں بھی یہ خیال آیا؟ یہ سن کے سارے درویشاں نے وجد آ گیا۔ فرمایا: رموز دانی اِسی کا ناں سے۔ فیر خلافت کی دستار اپنے پاک ہاتھ تے باندھ کے فرمایا: جاؤ سلسلۂ نقشبندیہ میں بیعت کر کے اپنے والد بزرگوار کا ناں روشن کرو، جڑے تم ہوو گے اُڑے میں تمہارے نال ہوں گا۔", "murshideen.015": "سلسلۂ نقشبندیہ میں بیعت و خلافت", "murshideen.016": "شیخ صاحب آپ نے جالندھر لے گئے اور آپ کے والدِ بزرگوار شمس العرفانؒ کے پیشوا حاجی حافظ محمود جالندھریؒ تے سلسلۂ نقشبندیہ میں بیعت کروایا۔ کیونکہ والد بزرگوار نے آپ نے وصیت کری تھی کہ پہلاں سات سال میرے مزار پہ بیٹھنا اور اپنی اور میری والدہ کی خدمت کرنا، اِس خاطر سلوکِ نقشبندیہ پورا کرن کی غرض تے والد بزرگوار کے مزار مبارک پہ روز حاضر ہوتے اور مزار مبارک تے روحانی تربیت پاتے رہے۔ آپؒ نے سلوکِ مجددیہ تھوڑے عرصے میں طے فرمایا اور حاجی صاحبؒ نے آپ نے خلافت کی دستار عطا فرمائی۔", "murshideen.017": "شمس الکونین کی سنت زندہ کرن کی خدمتاں", "murshideen.018": "۱۔ بیواؤں کا نکاح", "murshideen.019": "خواجہ صاحب اپنی کتاب «سرمایۂ سہاگن» میں فرماویں سیں کہ لگاتار چار برس کی ان تھک محنت کے بعد ۲۱ مارچ تے ۲۳ مارچ ۱۸۹۲ء مطابق ۱۳۰۹ھ قصبہ کلانور ضلع رہتک میں جلسۂ اسلامیہ کروایا، جس میں تیرہ ہزار سات سو پینسٹھ کرسیاں لائی گئیں اور اک گھنا بڑا سٹیج سجایا گیا جس پہ ڈپٹی کمشنر رہتک، بڑے بڑے افسراں اور علماء و مشائخ نے بٹھایا۔ کلانور کے بڑے بڑے گھرانیاں میں بیواؤں کے دھڑا دھڑ نکاح ہون لگے۔ تیرہ سو برس بعد اِس فرمانِ الٰہی «اپنی بیواؤں کے نکاح کرو» (القرآن) پہ راجپوت قوم نے راضی کر کے بیواؤں کے نکاح کی مری ہوئی سنت نے زندہ کرن کا شرف پایا۔ اِس تے پہلاں راجپوت قوم اِسے بے غیرتی کا کم سمجھے تھی۔ گھنا سارا روپیہ غریباں اور فقیراں میں ونڈیا گیا اور ولیمے کی دعوت بھی سب نے دی۔", "murshideen.020": "معزز لوگاں نے لوٹیاں میں پانی اور لون ڈلوا کے عہد و پیمان لیا کہ آج تے ہم نے خوشی اور رضامندی تے اِس ہندوانی اور کفر آلی رسم نے چھوڑ دیا اور دل و جان تے خدا اور رسول ﷺ کا حکم منظور کیا۔ اب سدا بیواؤں کے نکاح کرتے رہواں گے۔ جے اِس پہ کوئی عمل نا کرے گا تو اُس تے سارے لوگ ملنا جلنا اور رشتہ ناطہ چھوڑ دیویں گے۔ جو کوئی بیوہ کا نکاح کرے گا ہم اُس میں خوشی تے شریک ہویا کراں گے، جیسے کنواری چھوری کے نکاح میں شریک ہوویں سیں، اور جو بندہ عیب اور طعنہ سمجھ کے شریک نا ہووے تو برادری اُسے کڈھ دیوے۔ جس طرح ہم نے بیواؤں کا دوجا نکاح جاری کیا اُسی طرح ہم شرعی پردہ جاری کراں گے، یعنی جو لوگ غیر محرم سیں اُن تے اپنی بہو بیٹیاں نے جتنا ہو سکے گا پردہ کروان میں گھنی کوشش کراں گے۔", "murshideen.021": "۲۔ یتیم پروری", "murshideen.022": "آپؒ جڑے بھی جاتے بیواؤں کے نکاح کی تبلیغ کے نال نال یتیم پروری کی بھی تلقین فرماتے، کیونکہ یتیماں کا بیواؤں کے نال گہرا تعلق سے۔ فرماتے: یتیم پالن آلے نے جو خوشخبری نبی کریم ﷺ نے دی سے وہ کسے عابد، زاہد، شہید یا کسے بڑے تے بڑے نیک بندے خاطر نہیں دی۔ فرمانِ مصطفیٰ ﷺ سے: میں اور یتیم نے پالن آلا جنت میں اِس طرح نال ہوواں گے جس طرح یہ دو انگلیاں۔ آپ ﷺ نے شہادت کی انگلی اور اُس کے نال آلی انگلی نے ملا کے اشارہ فرمایا۔ اِس خاطر آپؒ کے کول جو کچھ بچتا سب یتیماں اور بیواؤں میں ونڈ دیتے۔", "murshideen.023": "۱۵ جون ۱۹۰۵ء نے یتیم خانہ خالقیہ اور انجمن خالقیہ قائم ہوئے۔ فیر قرآن پاک کی تعلیم کا بندوبست کیا۔ بعد میں ۱۹۰۶ء میں پرائمری، ۱۹۱۴ء میں مڈل اور ۱۹۲۵ء میں ہائی سکول اور فیر انٹر کالج منظور ہویا۔ اِن اداریاں تے ہندو اور سکھ بالک بھی فیضیاب ہوئے۔ مسلماناں، برہمناں، بنیاں، سکھاں اور چماراں کے بالک بھی پڑھیا کرتے، اور افریقہ تے بھی تین یتیم بالک تعلیم خاطر آئے۔", "murshideen.024": "اِسی طرح سید امیر حسین شاہ صاحب ساکن رحیم یار خان نے انیس مربعے زمین آپؒ کے ناں کروا دی تاکہ آپؒ اپنا پکا آستانہ بنواویں۔ پر آپؒ نے وہ ساری زمین اپنے یتیم خانے کے ناں کروا دی اور فرمایا: ہمیں زمیناں کی لوڑ نہیں۔ آپؒ نے اپنی رہائش سدا پھوس کے چھپر آلے کچے مکان میں ہی رکھی پر یتیماں، مسافراں اور سکول کے ملازماں خاطر پکے مکان بنوائے۔ جے کسے افسر تے ملتے جو درِ دولت پہ حاضر ہوتا تو اک ہاتھ تے مصافحہ کرتے، جو افسر نذرانہ پیش کرتے وہ خود نا رکھتے بلکہ یتیم خانے میں جمع کروا دیتے اور اُسے فرماتے کہ آپ کا نذرانہ یتیم خانے میں اِس خاطر جمع کروایا سے کہ اِس کے بدلے خداوندِ کریم دنیا اور آخرت میں ہزار گنا عطا فرماوے۔ جد کوئی مہمان مٹھائی وغیرہ لیاتا تو اتباعِ سنت میں خود اپنے شفقت آلے ہاتھ تے یتیماں اور درویشاں میں ونڈ دیتے۔", "murshideen.025": "۳۔ ختمِ نبوت کی حفاظت", "murshideen.026": "جد مرزا غلام احمد قادیانی نے نبوت کا جھوٹا دعویٰ کیا تو ۱۹۰۲ء میں مباہلے خاطر ہزاراں اہلِ اسلام لاہور اکٹھے ہوئے۔ اہلِ سنت و جماعت کی طرف تے تین حضرات — شمس الکونین خواجہ محمد عبدالخالقؒ، پیر مہر علی شاہ گولڑویؒ اور انور شاہ کشمیریؒ — چنے گئے۔ مرزا قادیانی نے مباہلے کی شرط رکھی کہ میدان میں سادہ قلم دوات رکھ دی جاوے، قدرت میری نبوت کی تصدیق کرے گی۔ اِن حضرات نے قبول کر لیا۔ دوجے دن مباہلے کے میدان میں لوگ ٹولیاں کی ٹولیاں آن لگے اور یہ تینوں بزرگ حضرات بھی پہنچ گئے، پر مرزا قادیانی میدان میں آن کی جگہ قادیان بھاج گیا۔", "murshideen.027": "دسمبر ۱۹۲۴ء میں آپؒ روضۂ مبارک مجدد الفِ ثانیؒ سرہند شریف میں ٹھہرے ہوئے تھے۔ ضلع رنگ پور بنگال کے مسلماناں نے خط لکھیا کہ مرزا قادیانی کا بیٹا مرزا بشیر الدین قادیانی مسلماناں نے مباہلے کا چیلنج دے رہیا سے، کیا آپؒ مباہلے خاطر تیار ہو؟ جواب دیا کہ اِن شرطاں پہ مباہلے خاطر تیار ہوں: (۱) وہ مباہلے کی تاریخ کا خود اعلان کرے۔ (۲) مباہلے کی جگہ ہندوستان کے کسے بڑے شہر جیسے دہلی، لاہور، کلکتہ یا بمبئی میں ہونی چاہیے۔ (۳) مباہلہ کھلے مجمعے میں ہووے۔ جد مرزا نے یہ شرطاں سنیں تو پنجاب بھاج گیا۔", "murshideen.028": "۴۔ اوّل وقت نماز کا اجراء", "murshideen.029": "۱۹۲۵ء میں آپؒ نے سپنے میں دیکھیا کہ اک گھنے مشہور بزرگ پہ سخت عذاب ہو رہیا سے۔ پتہ لگا کہ یہ عذاب نمازاں دیر تے پڑھن اور جماعت چھوڑن کی وجہ تے ہو رہیا سے۔ اُس دن تے آپ ساری نمازاں، خاص کر کے فجر اور ظہر پڑھن میں گھنی جلدی فرمان لگے، اور حنفی مسلک کے اوقات کے مطابق نماز کا وقت شروع ہوتے ہی باجماعت نماز کا انتظام فرمایا کرتے تھے۔", "murshideen.030": "سورۃ الماعون میں ارشادِ باری تعالیٰ سے: <span class=\"kk-ar\" style=\"display:block\">فَوَيْلٌ لِّلْمُصَلِّيْنَ ۝ الَّذِيْنَ هُمْ عَنْ صَلَاتِهِمْ سَاهُوْنَ</span> — اُن نمازیاں خاطر ویل یعنی جہنم کے اک کھڈے کا عذاب سے جو اپنی نمازاں میں غفلت کریں سیں۔ نبی کریم ﷺ نے ارشاد فرمایا: اوّل وقت میں نماز پڑھنا حق تعالیٰ کی خوشنودی کا سبب سے۔", "murshideen.031": "امام غزالیؒ، سیدنا شیخ عبدالقادر جیلانیؒ، امامِ ربانی مجدد الفِ ثانیؒ اور شاہ غلام علی دہلویؒ جیسے اونچے مرتبے آلے مشائخ بھی اوّل وقت میں نماز پڑھیا کرتے اور اپنے مریداں نے بھی اِس کی تلقین فرمایا کرتے تھے۔ نال ہی ہر سمجھدار بندہ یہ بات چنگی طرح سمجھ سکے سے کہ رب کا حکم ہو جان کے بعد بغیر شرعی عذر کے نماز میں دیر کرنا محبت کے دعوے تے دور اور حکم عدولی کے نیڑے سے، جد کہ بندہ وہی محبوب ہووے سے جو وقت ہوتے ہی اپنے رب کے حضور سجدے میں گر جاوے۔ اِس خاطر اوّل وقت نماز پڑھن کی کوشش کرنی چاہیے۔", "murshideen.032": "وصال مبارک", "murshideen.033": "تقریباً رات کے اک بجے سائیں صاحبؒ نے جگایا اور فرمایا: مجھے وضو کروا کے تہجد کے نفل پڑھاؤ۔ نفلاں کے بعد سجدے میں سر رکھ کے دعا مانگی: اے اللہ! مجھے جان نکلن کی تکلیف نا دینا اور سجدے کی حالت میں شہادت کا درجہ عطا فرمانا۔ دعا کے بعد فرمایا: عبدالرزاق! اب مجھے گھنی بے چینی سے، دباتے رہو۔ اِسی طرح فجر کا ویلا ہو گیا، آپؒ نے وضو کر کے فجر کی سنتاں پڑھیں۔ جماعت کھڑی ہو گئی۔ آپؒ کے نال سید دین علی شاہؒ، سائیں عبدالرزاقؒ اور مولوی سراج الدین مقتدی تھے۔ دوجی رکعت کے آخری سجدے میں اک دم ساری چھت گر پڑی، اور ۷ محرم الحرام ۱۳۵۰ھ نے ۸۰ برس کی عمر مبارک میں آپؒ اپنے خالقِ حقیقی تے جا ملے۔", "murshideen.034": "شمس العارفین سائیں عبدالرزاق خالقی نقشبندیؒ<span class=\"mk-hint\">تعارف پڑھو ▾</span>", "murshideen.035": "شمس العارفین، سراج السالکین<br>قطبِ عالم حضرت سائیں عبدالرزاق خالقی نقشبندیؒ", "murshideen.036": "کشف اور کرامات تو تھلے درجے کی بات سے، اصل تو اتباعِ سنت اور شریعتِ مطہرہ کی پابندی سے کیونکہ مریداں نے پیشوا کا عمل دیکھ کے اس کی پیروی کرنی ہووے سے۔ (شمس العارفینؒ)", "murshideen.037": "اکثر فرمایا کرتے: شریعت بیج سے، جے بیج ای خراب سے تو درخت کیسے ٹھیک ہووے گا۔ پہلاں بھی شریعت سے اور آخر بھی شریعت۔ جے کوئی ہوا میں اُڈتا ہویا بھی آوے پر شریعت کا بال برابر بھی چھوڑن آلا ہووے تو وہ جادوگر ہو سکے سے پر اللہ آلا نا ہو سکتا۔", "murshideen.038": "ولادت باسعادت", "murshideen.039": "آپؒ کے فرمودات کے مطابق آپ کی ولادت باسعادت ۱۸۹۰ء میں ہوئی۔ ولادت کے پاچھے آپ کی دادی نے نیک بختی اور لمبی عمر خاطر آپ نے مسجد میں بھجوا دیا۔ آپ فرمایا کرتے کہ اللہ تعالیٰ کا احسان سے کہ ساری عمر مسجداں میں ای گزر گئی۔", "murshideen.040": "شروع کی تعلیم", "murshideen.041": "جب آپ کی عمر پانچ چھ سال ہوئی تو اسی ویلے نمازِ پنجگانہ اور سات آٹھ سال کی عمر تے نمازِ تہجد پابندی تے پڑھنی شروع کر دی جو اللہ کے فضل تے آخری سانس تئیں قضا نا ہوئی۔", "murshideen.042": "جب تم نے نمازِ تہجد شروع کری، تب آپ کی عمر بس سات سال تھی", "murshideen.043": "نا کوئی تکبیرِ اولیٰ رہی نا کوئی نماز قضا ہوئی، میرے سائیںؒ پیا، تیری کیا بات سے", "murshideen.044": "شروع کی تعلیم مدرسہ کلانور میں پائی۔ دوسری جماعت کے پاچھے مجذوبانہ حالت کی وجہ تے سکول چھوڑ دیا۔ قرآن شریف مسجد کے امام حافظ عبدالرحمٰن صاحب تے پڑھیا۔", "murshideen.045": "خواجہ صاحبؒ کی خدمت میں حاضری", "murshideen.046": "بزرگانِ دین فرماویں سیں کہ جو کوئی یو چاہوے کہ وہ اللہ کا مقرب بن جاوے تو وہ اولیاء اللہ کی صحبت اختیار کرے۔", "murshideen.047": "چنانچہ جب آپ کی عمر مبارک بارہ سال ہوئی تو آپؒ کے والد آپ نے خواجہ صاحبؒ کی خدمت میں لے گئے۔ خواجہ صاحبؒ نے آپ نے گود میں لیا اور پیار کریا۔ آپؒ کے والد صاحب نے عرض کری کہ یو ہر ویلے روتا اور قرآن شریف پڑھتا رہوے سے اور کسے تے بات نا کرتا، اتنا ہو جاوے کہ اسے کھان پین، کپڑے پہرن اور بولن کی سمجھ آ جاوے۔ خواجہ صاحبؒ نے فرمایا: بیاہ بھی ہووے گا، اولاد بھی ہووے گی، نوکری بھی کرے گا اور سردار بھی ہووے گا، اس کا ناں نبی کریم ﷺ کے مقبول بندیاں کی فہرست میں لکھیا جا چکیا سے۔ آپؒ آپ فرماویں تھے کہ خواجہؒ صاحب کی نگاہِ فیض تے میرے اوپر جو معاملہ گزریا وہ بیان تے باہر سے۔ اسی دوران آپؒ خواجہ صاحبؒ تے بیعت ہو گئے تھے۔", "murshideen.048": "منازلِ سلوک طے کرنا", "murshideen.049": "حضور سائیںؒ جی نے فرمایا: میں ۴۰ سال خواجہ صاحبؒ کی خدمت میں رہیا پر ان کے سامنے کدے نا بولیا۔ اک دن خواجہ صاحبؒ میری کمر پہ سوار تھے اور نعلین مبارک سید دین علی شاہ صاحبؒ نے پکڑ رکھے تھے۔ آپؒ نے روتے ہوئے یوں دعا فرمائی:", "murshideen.050": "یا اللہ! جتنا میں اس عبدالرزاق تے خوش ہوں تو بھی اتنا ای خوش ہو جا، جتنی اس نے میری خدمت کری سے مخلوق بھی اس کی اتنی ای خدمت کرے۔", "murshideen.051": "اک بار سید دین علی شاہ صاحبؒ نے خواجہ صاحبؒ تے عرض کری کہ حضور! جے عبدالرزاق فوج میں ہوتا تو آج یو بھی سردار ہوتا۔ آپؒ اٹھ بیٹھے اور فرمایا: شاہ جی! تم کیا سمجھو ہو، فوجی سردار تو اس کے پیراں میں رُلیں گے۔ آپؒ آپ فرمایا کرتے کہ نا تو میرے میں علم سے، نا میں نے تسبیح پھیری اور نا ورد وظیفے کرے، یو سب خواجہؒ صاحب کی صحبت، نگاہ اور دعا و برکت کا فیض سے۔ میں نے کدے خواجہ صاحبؒ کے سامنے آنکھ اٹھا کے بھی نا دیکھیا اور نا کدے آپؒ کے سامنے بولیا۔", "murshideen.052": "تو چھتیس سال شیخ کے کول رہیا، شیخ کا دیدار ای تیرا وظیفہ تھا", "murshideen.053": "آخری سانس تئیں تم جدا نا ہوئے، میرے سائیں پیا، تیری کیا بات سے", "murshideen.054": "یتیماں کی پرورش", "murshideen.055": "یتیماں کی پرورش میں آپ کا کوئی ثانی نا تھا۔ معاشرے کے ٹھکرائے ہوئے، مصیبت کے مارے یتیم بالکاں کی مدد اور سہارے خاطر ہر ویلے بے چین اور بے قرار دِکھیں تھے۔", "murshideen.056": "اس بارے میں حافظ علیم الدین صاحب نے بیان کریا کہ ۱۹۶۵ء میں حضور سائیںؒ جی حج تے واپس تشریف لائے تو ہم گھنے سارے آدمی دیپالپور شریف تے حضور کے استقبال خاطر اوکاڑہ سٹیشن پہ آئے۔ موج دین رزّاقی گلاب کے پھولاں کا ہار لے کے آیا۔ ہم نے حضور نے گاڈی تے اتاریا۔ موج دین نے حضور کے گلے میں ہار گیرنا چاہیا پر حضور نے وہ ہار موج دین کے گلے میں گیر دیا اور فرمایا: یو فضول خرچی سے، دکھاوا سے۔ اتنے پیسے یتیم خانے میں جمع کرا دیتے تو بہتر تھا۔", "murshideen.057": "فرمایا کرتے کہ یتیم کے سات ایسا سلوک کرنا چاہیے کہ اسے یتیمی کا ذرا بھی احساس نا ہون پاوے۔ جے بھیک منگوا کے پالنا سے تو فیر وہ آپ بھی اپنا پیٹ پال سکیں سیں، تمہارا کیا احسان؟ بلکہ یتیماں تے چندہ منگوانا اور فیر آپ بھی ورتنا دونوں حرام سیں۔", "murshideen.058": "یتیم بالکاں کی پکی بحالی خاطر ملک کی ونڈ ونڈ جگہاں پہ لاکھاں روپے کے خرچ تے دار الشفقت کے ناں تے یتیم خانے اور ان کے سات مسجداں اور تعلیمی ادارے بنوائے۔ ان یتیم خانیاں میں رہن آلے سینکڑاں یتیم اور لاوارث بالکاں نے دینی تعلیم کے سات سات عصری اور ووکیشنل تعلیم بھی دی جاوے تھی اور یوں انہاں نے معاشرے پہ بوجھ بنن کی بجائے عزت اور وقار آلی زندگی گزارن کے قابل بنایا جاوے تھا۔ یو ادارے حکومت تے باقاعدہ رجسٹرڈ اور منظور شدہ تھے اور ان میں بورڈ کی نگرانی میں امتحان لیے جاویں تھے۔", "murshideen.059": "آپؒ نے اپنی جدّی زرعی زمین اپنی اولاد میں ونڈ دی تھی تاکہ وہ عزت تے گزارا کر سکیں اور باقی ساری شہری جائیداد یتیم خانے کے ناں ہبہ فرما دی۔ حتیٰ کہ وصال تے پہلاں نذرانے کا اک لاکھ تیئیس ہزار روپیہ بھی یتیم خانے کے فنڈ میں جمع کروا دیا اور فرمایا: اولاد لائق ہوئی تو آپ بنا لے گی، نالائق ہوئی تو پہلا بھی ضائع کر دے گی۔ اللہ کی راہ میں خرچ کرنا چاہیے جو اگے کام آوے۔", "murshideen.060": "خطاب سراج السالکین", "murshideen.061": "رسالدار محمد لقمان رزّاقی صاحب بیان کریں سیں کہ ذہن میں اکثر یو سوال آیا کرتا کہ اللہ تعالیٰ کے خاص بندیاں نے ونڈ ونڈ قسم کے خطاب کیسے مل جاویں سیں۔ اک دن نمازِ فجر تے کچھ دیر پہلاں میں مسجد میں بیٹھیا ہویا تھا کہ اونگھ آ گئی۔ دیکھیا کہ امامِ ربانی مجدد الفِ ثانیؒ اور قبلۂ عالم حضور سائیںؒ جی مسجد کی محراب کے سامنے کھڑے سیں۔ حضرت مجدد صاحبؒ نے سائیںؒ صاحب نے سینے تے لایا اور فیر فرمان لگے: آؤ تمہارے سراج السالکین کا ٹھپہ لا دیاں۔ بس فیر آنکھ کھل گئی اور یوں سوال کا جواب مل گیا۔", "murshideen.062": "خطاب شمس العارفین", "murshideen.063": "آپؒ اک بار سید جماعت علی شاہؒ کے خلیفہ چراغ علی شاہؒ، جن کا مزارِ مبارک لاہور والٹن میں سے، کے کول مرالہ شریف تشریف لے گئے۔ شاہ صاحبؒ نے اپنی پگڑی اتار کے گلے میں گیر لی اور دونوں بانہہ کھڑی کر کے فرمان لگے کہ میں کیا بتاؤں کہ میرے گھر کون آ گئے سیں، شریعت منع کرے سے، یو سمجھو کہ کیڑی کے گھر نرائن آ گئے سیں۔ اس پہ حضور سائیںؒ جی نے فرمایا: شاہ جی گھنے بڈے درویش سیں، دنیا کے چوتھے حصے کے مالک سیں۔ شاہ جی فرمان لگے کہ جی آپؒ نے میرا بھید کھول دیا، معافی چاہوں ہوں، میرے تے بھی اب رہیا نا جاتا، میں بھی آپ کا بھید کھولوں ہوں، آپؒ ساری دنیا کے مالک سیں اور اس ویلے اک ای اک سیں۔ اک بار شاہ صاحبؒ نے فرمایا کہ حضور سائیںؒ جی کا خطاب شمس العارفین سے۔", "murshideen.064": "وصالِ پُرملال", "murshideen.065": "آپؒ بواسیر کے آپریشن خاطر کنعان ٹرسٹ ہسپتال لاہور میں داخل تھے جتھے آپ کی منجی پہلی صف میں بچھا دی جاوے تھی اور مٹی تے تیمم کروایا جاوے تھا اور آپؒ لیٹے لیٹے اشاریاں تے نماز باجماعت ادا فرمایا کرتے۔ ۲۴ مارچ ۱۹۸۲ء نے دوبارہ کنعان ٹرسٹ ہسپتال لاہور میں داخل ہوئے۔", "murshideen.066": "آخر منگل کی رات آپ نے استغراق ہویا اور لگ بھگ ۲۰ گھنٹے استغراق کی حالت میں رہ کے بدھ کے دن شام ۴ بجے، تاریخ ۳۱ مارچ ۱۹۸۲ء بمطابق ۴ جمادی الثانی ۱۴۰۳ھ، کم و بیش ۹۵ سال کی عمرِ مبارک میں اپنے خالقِ حقیقی تے جا ملے۔ وصال کے ویلے اپنے دونوں ہاتھاں کی شہادت کی انگلیاں اٹھا لیں اور سات ای زبانِ مبارک تے اسمِ ذات اللہ نکلیا۔ وصال کے پاچھے سب نے دیکھیا کہ قلبِ سلیم ذکرِ الٰہی میں ہل رہیا تھا۔ وصالِ مبارک کے فوراً پاچھے ریڈیو پاکستان لاہور تے یو اعلان ہویا: آفتابِ طریقت کم و بیش اک صدی تئیں جگمگا کے آج بدھ کے دن ۳۱ مارچ ۱۹۸۲ء بمطابق ۴ جمادی الثانی ۱۴۰۳ھ نے غروب ہو گیا۔", "murshideen.067": "جسدِ مبارک نے غسل دیا گیا اور وصیت کے مطابق اس چادر میں لپیٹیا گیا جو شہادت کے ویلے خواجہ صاحبؒ کے جسمِ مبارک پہ تھی، اور خواجہ صاحبؒ کے موئے مبارک بھی آپؒ کے کفن میں رکھے گئے۔ گھنی بھیڑ کی وجہ تے آپ کی نمازِ جنازہ تین بار پڑھائی گئی۔ جمعے کے دن ۲ اپریل نے وصیت کے مطابق معلق حالت میں لکڑی کے صندوق میں جسدِ مبارک رکھ کے سپردِ خاک کر دیا گیا۔", "murshideen.068": "خلفاءِ کرام اور سجادگان", "murshideen.069": "آپؒ کے مشہور خلفاءِ کرام تین سیں جن کے اسمائے گرامی یو سیں:", "murshideen.070": "۱۔ امام الذاکرین حضور سائیں محمد عظیم اللہ رزّاقی نقشبندیؒ، دربارِ عالیہ عظیم نگر شریف ضلع بہاولنگر۔<br>۲۔ بے حد سوہنے خواجہ نور احمد خاں رزّاقی نقشبندیؒ، دربارِ عالیہ لالہ موسیٰ شریف ضلع گجرات۔<br>۳۔ ایڈووکیٹ حضور محمد شریف رزّاقی نقشبندیؒ، دربارِ عالیہ سیل گاؤں ضلع پاکپتن شریف۔", "murshideen.071": "آپؒ کے دو شہزادے تھے، جن کے اسمائے گرامی یو سیں:", "murshideen.072": "۱۔ صاحبزادہ فقیر محمد رزّاقی نقشبندی، اللہ تعالیٰ آپ کا سایہ دیر تئیں ہمارے سراں پہ قائم رکھے۔<br>۲۔ صاحبزادہ بلال احمد رزّاقی نقشبندیؒ۔ آپ کا وصال ۲۰۲۵ء میں ہویا تھا۔ اللہ تعالیٰ آپ کے درجات بلند فرماوے۔", "murshideen.073": "امام الذاکرین سائیں محمد عظیم اللہ رزّاقی نقشبندیؒ<span class=\"mk-hint\">تعارف پڑھو ▾</span>", "murshideen.074": "امام الذاکرین، سراج السالکین، قطبِ دوراں<br>مظہرِ نورِ خدا قبلۂ عالم سائیں محمد عظیم اللہ رزّاقی نقشبندیؒ", "murshideen.075": "ولادت اور بچپن", "murshideen.076": "شناختی کارڈ کے مطابق آپؒ یکم جنوری ۱۹۳۴ء نے انڈیا کے موضع سیہوانی ضلع حصار میں راجپوت گھرانے کے اک نیک سیرت بندے حاجی حسین علی صاحبؒ کے گھر پیدا ہوئے۔ والدہ ماجدہ کا تعلق ڈھنکوٹ کے محلہ میر خان تے تھا جن کا کنبہ اس ویلے گوٹھ محمد ابڑو میں رہوے سے۔ آپ بچپن میں گھنے بیمار رہیا کرتے، چپ رہتے یا فیر روتے رہتے تھے۔", "murshideen.077": "بیعتِ طریقت", "murshideen.078": "سورۃ المائدہ میں ارشادِ باری تعالیٰ سے: <span class=\"kk-ar\" style=\"display:block\">يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوا اتَّقُوا اللّٰهَ وَابْتَغُوْٓا اِلَيْهِ الْوَسِيْلَةَ وَجَاهِدُوْا فِيْ سَبِيْلِهٖ لَعَلَّكُمْ تُفْلِحُوْنَ</span> اے ایمان آلیو! اللہ تے ڈرو اور اس کی طرف وسیلہ ٹوہو اور اس کی راہ میں مجاہدہ کرو تاکہ تم فلاح پاؤ۔ (۳۵)", "murshideen.079": "اپنے بیعت ہون کا واقعہ ہمارے پیشوا آپ یوں بیان فرمایا کرتے کہ جب میں پانچویں جماعت میں پڑھوں تھا تو فوجی بھرتی کرن آئے تو میں بھی دوجے چھوریاں کے سات بھرتی ہو گیا۔ انہی دناں میں ڈونگہ بونگہ میں راؤ مراتب علی کے ڈیرے پہ حضور سائیںؒ جی تشریف فرما تھے۔ میں زیارت خاطر حاضر ہویا تو سائیںؒ جی نے اسی ویلے میرے تے بیعت لے لی۔", "murshideen.080": "پاچھے تے حضور سائیںؒ جی سونڈھا شریف تشریف لائے تو میری والدہ نے آپ نے دیکھتے ای کہیا کہ یو تو وہی بزرگ سیں جو انڈیا میں عامل نے میرے ناخن میں میرے تے دکھائے تھے۔ میری والدہ راہ میں کھڑی ہو گئیں اور سائیںؒ جی تے عرض کری: میں نے عظیم اللہ تو گھنا پہلاں ای آپ نے دے دیا تھا۔ سائیںؒ جی نے فرمایا: ہاں یو میرا ای سے۔ ۱۹۵۵ء میں حضور سائیںؒ جی میرے تے اپنے سات دیپالپور شریف لے گئے اور اک دن کپڑے دھوتے ہوئے گیرو رنگ کا ڈھیلا منگوا کے اپنے کپڑیاں نے رنگن کے سات میرے کپڑیاں نے بھی گیرو رنگ تے رنگ دیا۔", "murshideen.081": "منصبِ خلافت", "murshideen.082": "حضور سائیںؒ جی کی طرف تے خلافت کا منصب ملن کا واقعہ آپؒ یوں بیان فرمایا کرتے: حضور سائیںؒ جی دیپالپور شریف مسجد میں تشریف فرما تھے۔ میں صبح حلقۂ ذکر کے پاچھے مسجد کے صحن میں جا کے گیہوں صاف کرن لگیا۔ حضور سائیںؒ جی نے مراقبے کے پاچھے میرے تے یاد فرمایا اور اپنی سجی بانہہ کی لپیٹ میں لے کے ارشاد فرمایا: اللہ اللہ کرایا کرو۔ میں نے عرض کری کہ حضور سارے لوگ خوب اللہ اللہ کریں سیں۔ فرمایا: پہلاں ان سب نے مرید کریا کرو، پاچھے اللہ اللہ سکھایا کرو۔ اس ویلے میرے پہ گھنا ڈر طاری ہویا، سارے جسم پہ پسینہ آ گیا۔ فرمایا: خواجہ صاحبؒ نے میرے تے بھی اسی طرح فرمایا تھا کہ ایسے توجہ دیا کرو اور ایسے اللہ اللہ کرایا کرو۔", "murshideen.083": "خطاب امام الذاکرین", "murshideen.084": "ناچیز مؤلف نے اپنے گام میں حضور سائیںؒ جی کے سالانہ عرس مبارک کے سلسلے میں اشتہار چھپوانے تھے۔ اسی سوچ میں سو گیا کہ حضور قبلۂ عالمؒ کے نامِ مبارک کے سات آپ کی شان کے لائق کون سا لقب لکھواؤں۔ خواب میں دیکھیا کہ ناچیز حضور سائیںؒ جی کی قبرِ انور کے کول کھڑا سے اور آپؒ کے مزار کے آلے دوالے جتھے تئیں میری نظر پہنچے تھی فرش تے عرش تئیں نور ای نور نظر آوے تھا اور آپ کی قبرِ انور تے آواز آئی: عظیم اللہ! امام الذاکرین سے۔", "murshideen.085": "وصال مبارک", "murshideen.086": "آپ گھنی دیر بیمار رہن کے پاچھے ۱۴ جمادی الاوّل ۱۴۳۴ھ بمطابق ۲۷ مارچ ۲۰۱۳ء، بدھ کے دن صبح آٹھ بجے سونڈھا شریف میں ذکر اللہ کرتے ہوئے لگ بھگ ۸۳ سال کی عمر میں اپنے خالقِ حقیقی تے جا ملے۔ آپ کی چھوٹی بہن حکومت بی بی کے کہن مطابق وصال کے نیڑے آپؒ نے فرمایا کہ حضور سائیںؒ جی میرے کول بیٹھے سیں۔", "murshideen.087": "آپ کی تدفین ۲۹ مارچ، جمعۃ المبارک کے دن، بہاولنگر روڈ پہ ڈونگہ بونگہ تے کچھ پہلاں سورج گنج موڑ پہ آپ کی مسجد کے صحن کے نیڑے کری گئی، جتھے اس ویلے سائیں حضورؒ کے مزارِ اقدس کے ڈیزائن پہ آپ کا روضۂ اقدس بن رہیا سے۔ مخلوقِ خدا دن رات آپؒ تے فیض پا رہی سے۔", "murshideen.088": "تصویراں اور مزاراں کی تفصیل جلد پا دی جاوے گی، ان شاء اللہ۔", "mubalighin.001": "مبلغاں کا تعارف", "mubalighin.002": "تصویراں اور ویڈیو جلد پا دی جاویں گی، ان شاء اللہ۔", "markaz.001": "وڈا مرکز", "marakiz.001": "چھوٹے مرکز اور مدرسے", "marakiz.002": "اسلام پور", "marakiz.003": "کوٹلی نجابت", "marakiz.004": "وہاڑی", "marakiz.005": "کوٹ مصری خان", "marakiz.006": "مہاجر گوٹھ", "marakiz.007": "گوٹھ ابڑو", "marakiz.008": "35 چک", "marakiz.009": "راؤ گڑھ", "marakiz.010": "باقی مرکزاں اور مدرسیاں کی تفصیل جلد پا دی جاوے گی، ان شاء اللہ۔", "bayanat.001": "بیان", "bayanat.002": "کسے بیان پہ دباؤ — ویڈیو یوٹیوب پہ چالے گی۔", "kutub.001": "کتاباں", "kutub.002": "حرف حرف تاثیر", "kutub.003": "<span>مؤلف:</span> بانی اور قائد تحریک اتباعِ سنت پاکستان، مذہبی سکالر کرامت علی رزّاقی عظیمی مجددی نقشبندی <span class=\"lat\">(M.A, L.L.B)</span>", "kutub.004": "<span>معاونت:</span> انجینئر شعیب عالم عظیمی مجددی (ایم اے علومِ اسلامیہ)، <span class=\"lat\">HOD</span> الیکٹریکل ٹریڈ، گورنمنٹ ٹیکنیکل ٹریننگ انسٹی ٹیوٹ لودھراں", "kutub.005": "صفحے: <span class=\"lat\">136</span>  • چھپائی: اکتوبر <span class=\"lat\">2026</span>", "kutub.006": "تحریک اتباعِ سنت پاکستان کا تعارف اور اس کے مقصد", "kutub.007": "ہمارا مقصد شریعت اور سنت کا فروغ", "kutub.008": "<span>مؤلف:</span> بانی اور قائد تحریک، پیرِ طریقت کرامت علی رزّاقی عظیمی نقشبندی <span class=\"lat\">(M.A, L.L.B)</span>", "kutub.009": "صفحے: <span class=\"lat\">19</span>", "kutub.010": "صراط الفلاح فی الدنیا والآخرۃ", "kutub.011": "دنیا اور آخرت میں کامیابی کا راہ", "kutub.012": "<span>مؤلف:</span> بانی اور قائد تحریک اتباعِ سنت پاکستان، پیرِ طریقت کرامت علی رزّاقی عظیمی نقشبندی <span class=\"lat\">(M.A, L.L.B)</span>", "kutub.013": "<span>معاونت:</span> انجینئر شعیب عالم عظیمی مجددی (ایم اے علومِ اسلامیہ)، <span class=\"lat\">HOD</span> الیکٹریکل ٹریڈ، گورنمنٹ ٹیکنیکل ٹریننگ انسٹی ٹیوٹ لودھراں", "kutub.014": "صفحے: <span class=\"lat\">83</span>  • چھپائی: مارچ <span class=\"lat\">2019</span>", "kutub.015": "دستورِ طریقت", "kutub.016": "جو راہِ سلوک کے ناں تے مشہور سے", "kutub.017": "<span>مؤلف:</span> بانی اور قائد تحریک اتباعِ سنت پاکستان، پیرِ طریقت، شیرِ مجدد بدرالہدیٰ کرامت علی رزّاقی عظیمی نقشبندی <span class=\"lat\">(M.A, L.L.B)</span>", "kutub.018": "<span>معاونت:</span> انجینئر شعیب عالم عظیمی مجددی (ایم اے علومِ اسلامیہ)، <span class=\"lat\">HOD</span> الیکٹریکل ٹریڈ، گورنمنٹ ٹیکنیکل ٹریننگ انسٹی ٹیوٹ لودھراں", "kutub.019": "صفحے: <span class=\"lat\">129</span>  • چھپائی: اکتوبر <span class=\"lat\">2016</span>", "gallery.001": "تصویراں کی گیلری", "bait.001": "بیعت اور طریقت", "bait.002": "بیعتِ طریقت", "bait.003": "سورۃ المائدہ میں ارشادِ باری تعالیٰ سے: <span class=\"kk-ar\" lang=\"ar\" style=\"display:block\">يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوا اتَّقُوا اللّٰهَ وَابْتَغُوْٓا اِلَيْهِ الْوَسِيْلَةَ وَجَاهِدُوْا فِيْ سَبِيْلِهٖ لَعَلَّكُمْ تُفْلِحُوْنَ</span> اے ایمان آلیو! اللہ تے ڈرو اور اس کی طرف وسیلہ ٹوہو اور اس کی راہ میں مجاہدہ کرو تاکہ تم فلاح پاؤ۔ (۳۵)", "bait.004": "شاہ ولی اللہ محدثِ دہلوی ارشاد فرماویں سیں کہ اس آیت میں وسیلے تے مراد مرشدِ کامل سے۔", "bait.005": "سورۃ لقمان میں ارشادِ باری تعالیٰ سے: <span class=\"kk-ar\" lang=\"ar\" style=\"display:block\">وَاتَّبِعْ سَبِيْلَ مَنْ اَنَابَ اِلَيَّ</span> اور اس کی راہ کی پیروی کرو جس نے میری طرف رجوع کریا۔ (۱۵)", "bait.006": "بیعتِ طریقت اور ارادت کے بارے میں سیدنا عبادہ بن صامت انصاریؓ فرماویں سیں کہ ہم نے رسول اللہ ﷺ تے ہر سوکھ اور اوکھ میں، ہر خوشی اور ناگواری میں آپ ﷺ کا حکم سنن اور ماننے پہ اور آپ ﷺ کے کسے حکم میں چون و چرا نا کرن پہ بیعت کری۔ (بخاری کتاب الاحکام)", "bait.007": "حجۃ الاسلام امام غزالیؒ فرماویں سیں کہ انبیاء کرام علیہم السلام کے علاوہ کوئی بھی ظاہری اور باطنی بیماریاں تے خالی نا۔ اس لیے ان بیماریاں نے دور کرن خاطر صوفیا کے سات طریقت میں داخل ہونا ضروری سے۔ جیسا کہ علمِ طب میں یو بات طے سے کہ طب کی کتاباں پڑھن کے باوجود کوئی آپ اپنا علاج نا کر سکتا بلکہ اس خاطر کوئی طبیب چاہیے۔ بالکل اسی طرح دل اور نفس کی بیماریاں کا علاج بھی آپ تے نا کریا جا سکتا، ان خاطر بھی اک مرشدِ کامل کی لوڑ سے۔", "bait.008": "سیدنا عبدالقادر عیسیٰؒ شاذلی فرماویں سیں کہ نبی کریم ﷺ کے صحابہ کرامؓ بھی نرا قرآن پڑھن تے اپنے نفساں کا علاج نا کر سکیں تھے، وہ بھی حاذقِ کونین ﷺ کے شفا خانے تے جڑے ہوئے تھے اور آپ ﷺ ان کا تزکیۂ نفس اور تصفیۂ قلب فرمایا کرتے۔ (حقائق عن التصوف)", "bait.009": "ہمارے دادا مرشد شمس الکونین فاتحِ قادیانیت خواجہ محمد عبدالخالقؒ فرماویں سیں: بیعت لفظ بیع تے نکلیا سے جس کا مطلب بِکنا سے۔ جس ویلے مرید بیعت ہووے سے تو اپنے سارے ارادے پیر کے حوالے کر دیوے سے۔ جو چیز بیچ دی جاوے تو آپس کی رضامندی بنا اسے واپس نا لیا جا سکتا۔ تو اسے دوجی جگہ کیسے بیچ سکے سے۔ (لمعاتِ کمالاتِ قادریہ)", "bait.010": "بیعتِ طریقت کا مقصد", "bait.011": "امامِ ربانی مجدد الفِ ثانیؒ فرماویں سیں کہ شریعت کے تین جز علم، عمل اور اخلاص سیں۔ اور طریقت شریعت کے تیجے جز یعنی اخلاص پاون کا ذریعہ سے۔ سو طریقت، شریعت تے کوئی الگ شے نا بلکہ شریعت نے کامل کرن میں شریعت کی خادم سے۔", "bait.012": "سو بیعت کا اصل مقصد اخلاص یعنی رضائے الٰہی پاونا سے۔ جس کا ذریعہ سیں: احکامِ شریعہ اور سنتِ نبوی ﷺ پہ پوری طرح چلنا، خدا تعالیٰ کی مرضی پہ راضی رہنا، لالچ نا کرنا، عبادت میں دل حاضر رکھنا، دین کے کام اخلاص تے کرنا، کسے نے حقیر نا سمجھنا، خود پسندی نا ہونا، غصے نے روکنا، ذکر اور فکر میں لگے رہنا۔ ایسے اخلاق اپنانے نے سلوک کہیں سیں۔", "bait.013": "جاننا چاہیے کہ اس میں نا کشف و کرامات ضروری سیں، نا دنیاوی کاماں میں کامیابی کا وعدہ سے، نا جھاڑ پھونک تے بیماری دور ہون کا دعویٰ، نا اگے پیش آن آلے واقعات کی خبر، نا یو تصرفات لازم سیں کہ پیر کی توجہ تے مُرید کی اصلاح آپ تے آپ ہو جاوے گی، نا ایسی باطنی کیفیتاں پیدا ہون کی کوئی میعاد سے کہ ہر ویلے یا گھٹ تے گھٹ عبادت کے ویلے لذت میں ڈوبیا اور مست رہوے اور عبادت میں خیال ای نا آویں، نا ذکر و شغل میں انوار وغیرہ کا دکھنا یا کسے آواز کا سنائی دینا ضروری سے، نا ای چوکھے خواباں کا دکھنا یا الہاماں کا صحیح و درست ہونا ضروری سے۔", "bait.014": "شیخِ کامل کی شرطاں", "bait.015": "اج کل جعلسازی اور شعبدہ بازی عروج پہ سے اور تصوف کا اصلی چہرہ بگاڑ کے پیش کریا جا رہیا سے۔ اس لیے سات سات شیخِ کامل کی پانچ شرطاں بیان کری جاویں سیں تاکہ سالکانِ طریقت اصل اور نقل کی پچھان آپ کر کے اپنے آپ نے گمراہی تے بچا سکیں۔", "bait.016": "اعلیٰ حضرت امام احمد رضا خان بریلویؒ پیرِ کامل کی شرطاں کے بارے میں فرماویں سیں کہ", "bait.017": "<b class=\"az-n\">۱۔ عقیدہ:</b> پیر مذہبِ اہلِ سنّت والجماعت کا صحیح العقیدہ ہووے کیونکہ بد مذہب گمراہ کا سلسلہ شیطان تئیں پہنچے گا نا کہ رسول اللہ ﷺ تئیں۔ (اج کل جے کسے پیر کا عقیدہ حضرات شیخین یعنی حضراتِ صدیق و عمر رضی اللہ عنہما کی افضلیت کے خلاف ہووے یا سیدنا امیر معاویہؓ کے بارے میں چوکھی رائے نا رکھے تو سُنّی مرید نے چاہیے کہ ایسے پیر کی بیعت فوراً توڑ کے کسے صحیح العقیدہ شیخ تے بیعت کر لے)۔", "bait.018": "عقیدے کی درستی کے بارے میں قیومِ زماں مرزا مظہر جانِ جاناں شہیدؒ دہلوی فرماویں سیں: اہلِ بیتِ اطہار تے محبت کا اظہار اور صحابہ کرامؓ کی برابر تعظیم لازم سے۔ یہی صراطِ مستقیم سے جو قیامت کے دن پُل صراط کی صورت میں ظاہر ہووے گی، جو دنیا میں اس راہ تے نا پھریا وہ قیامت کے دن اس پہ تے مضبوطی کے سات گزر جاوے گا۔ (مقاماتِ مظہری)", "bait.019": "<b class=\"az-n\">۲۔ علم:</b> اتنا علم شرط سے کہ کسے مدد بنا اپنی لوڑ کے مسئلے کتاب تے کڈھ سکے۔ مطالعہ کر کے اور لوگاں تے سُن سُن کے بھی عالم بن سکے سے۔ فارغ التحصیل ہون کی سند نا شرط سے نا کافی، بلکہ علم ہونا چاہیے۔ احکامِ شریعت امر و نہی، حلال و حرام، فرض و واجب، سنّت و مستحب اور کفر و اسلام یعنی علمِ فقہ تے خبردار ہووے۔ اور عربی عبارت چوکھی طرح پڑھ سکے۔", "bait.020": "ہمارے دادا مرشد شمس الکونین خواجہ محمد عبدالخالق شمس العرفانی نقشبندیؒ فرماویں سیں", "bait.021": "<b class=\"az-n\">۳۔ عمل:</b> اپنے علم پہ عمل کرن آلا ہووے۔ کوئی فرض، سنت یا مستحب اس تے قضا نا ہووے اتھے تئیں کہ کنگھا اور مسواک ورتے اور نماز باجماعت پڑھے اور جمعہ نا چھوڑے۔ شریعت پہ مضبوطی تے عمل کرے اور متابعتِ مصطفیٰ ﷺ میں کمی نا کرے۔", "bait.022": "<b class=\"az-n\">۴۔ اخلاص:</b> شمس الکونین خواجہ عبدالخالقؒ فرماویں سیں کہ پیر کا ہر عمل رضائے الٰہی خاطر ہووے۔", "bait.023": "<b class=\"az-n\">۵۔ سلسلہ اور خلافت:</b> پیر کا سلسلۂ طریقت صحیح ہووے یعنی وہ کسے پیر تے مرید ہووے اور خلافت یافتہ ہووے تاکہ اس کا ہاتھ دست بدست رسول اللہ ﷺ تئیں پہنچے۔ جو بندہ خلافت بنا بیعت کرے سے، اہلِ طریقت اسے زندیق جانیں سیں اور وہ گمراہ سے۔ اور کئی لوگ مرید ہوئے بنا نرے پیر زادے ہون کے گمان میں اپنے باپ دادا کے مزار پہ سجادہ نشین بن کے بیٹھ جاویں سیں۔ یا سلسلہ ای ایسا ہووے کہ کاٹ دیا گیا، اس میں فیض نا رکھیا گیا، لوگ ہوس خاطر اس سلسلے میں خلافت دیتے چلے آویں سیں، یا سلسلہ تو صحیح تھا پر وچکار کوئی ایسا بندہ آ گیا جو پیری کے قابل نا تھا، اس تے جو شاخ چلی وہ وچکار تے ٹوٹی ہوئی سے۔ ان ساری صورتاں میں ایسی بیعت تے ہرگز دستِ رسول اللہ ﷺ تئیں نا پہنچے گا اور فیض نا ملے گا کیونکہ بیل تے دودھ یا بانجھ تے بالک نا ہوتا۔", "bait.024": "شیخِ کامل کی بنیادی صفتاں", "bait.025": "جاننا چاہیے کہ پیرِ کامل میں یو پانچ صفتاں ضرور ہونی چاہییں۔", "bait.026": "سلطان العارفین شیخ بایزیدؒ بسطامی فرماویں سیں:", "bait.027": "<b class=\"az-n\">۱۔</b> پیر خوش اخلاق ہووے۔", "bait.028": "<b class=\"az-n\">۲۔</b> سخی ہووے۔", "bait.029": "<b class=\"az-n\">۳۔</b> عاجز ہووے۔", "bait.030": "ہمارے شمس الکونین خواجہ عبدالخالقؒ فرماویں سیں:", "bait.031": "<b class=\"az-n\">۴۔</b> پیر خلقِ عظیم رکھے تاکہ مرید کی مشکلاں سوکھی حل ہوویں۔", "bait.032": "<b class=\"az-n\">۵۔</b> پیر بیعت کرتے ویلے ہر موئے تن تے ذکر اسمِ ذات جاری کرا دیوے۔", "mamulat.001": "ختمِ خواجگانِ نقشبندیہ", "mamulat.002": "جاری کرن آلے: مظہرِ جمالِ مصطفائی خواجۂ خواجگان، حامئ بیوگان، دستگیرِ یتامیٰ، فاتحِ قادیانیت، قطب الاقطاب، شمس الکونین ابوسعد محمد عبدالخالق نقشبندیؒ", "mamulat.003": "نوٹ: ہر ورد تے پہلاں اک بار بسم اللہ شریف ضرور پڑھو۔", "mamulat.004": "(میں اللہ تے بخشش چاہوں ہوں جس کے سوا کوئی معبود نا، وہ زندہ اور قائم رکھن آلا سے اور میں اسی کی طرف رجوع کروں ہوں)۔", "mamulat.005": "سورۃ الفاتحہ <span class=\"kk-c\">۷ بار</span>", "mamulat.006": "درودِ خالقیہ", "mamulat.007": "(اے اللہ! اپنی ساری معلومات کے برابر درود بھیج ہمارے سردار حضرت محمد ﷺ پہ اور ہمارے سردار حضرت محمد ﷺ کی آل اور اصحاب پہ)۔", "mamulat.008": "سورۃ الم نشرح <span class=\"kk-c\">۷۹ بار</span>", "mamulat.009": "سورۃ الاخلاص بسم اللہ شریف کے سات <span class=\"kk-c\">۱۰۰۰ بار</span>", "mamulat.010": "سورۃ الفاتحہ <span class=\"kk-c\">۷ بار</span>", "mamulat.011": "یو سارے کلمے سو سو بار پڑھو:", "mamulat.012": "درودِ خالقیہ", "mamulat.013": "(گناہاں تے بچن کی طاقت اور نیکی کرن کی قوت اللہ کی طرف تے سے)", "mamulat.014": "(تیرے سوا کوئی معبود نا، تو پاک سے (ظلم کرن تے)، بیشک میں ای ظالماں میں تے ہوں، یعنی اپنے اوپر ظلم کر بیٹھوں ہوں)۔", "mamulat.015": "(یاحی و قیوم اپنی رحمت کے صدقے مدد فرما، اے مدد چاہن آلیاں کے مددگار)", "mamulat.016": "(اے عزت آلے! میرے تے مخلوق کی نظر میں عزت دار بنا)", "mamulat.017": "(اے حاجتاں پوری کرن آلے)", "mamulat.018": "(اے درجے بلند کرن آلے)", "mamulat.019": "(اے بلاواں نے دور کرن آلے)", "mamulat.020": "(اے مشکلاں نے کھولن آلے)", "mamulat.021": "(اے بیماریاں تے شفاء دین آلے)", "mamulat.022": "(اے دعاواں نے قبول کرن آلے)", "mamulat.023": "(اے مشکلاں نے حل کرن آلے)", "mamulat.024": "(اے سبب پیدا کرن آلے)", "mamulat.025": "(اے بے نیاز اور غنی بنا دین آلے)", "mamulat.026": "(اے ہر چیز تے بے نیاز اور بے پرواہ)", "mamulat.027": "(اے گھنا پیدا کرن آلے)", "mamulat.028": "(اے رزق دین آلے اور گھنا عطا کرن آلے)", "mamulat.029": "(اے انعام اور نعمتاں عطا کرن آلے)", "mamulat.030": "(اے بے نیاز! اپنے سوا سب تے بے نیاز کر دین آلے)", "mamulat.031": "(اے بے حد محبت کرن آلے)", "mamulat.032": "(اے ہر اک پہ بے حد رحم کرن آلے)", "mamulat.033": "(اے اپنے خاص اور چاہن آلیاں پہ گھنے ای مہربان)", "mamulat.034": "(اے گھنا کرم کرن آلے)", "mamulat.035": "(اے بخشن آلے)", "mamulat.036": "(اے گھنا درگزر اور پردہ پوشی کرن آلے)", "mamulat.037": "(اے مشکل کشا اور سوکھ کا دروازہ کھولن آلے)", "mamulat.038": "(اے سب کچھ عطا کرن آلے)", "mamulat.039": "(اے عزت دین آلے)", "mamulat.040": "(اے بلندی عطا کرن آلے)", "mamulat.041": "(اے روزی کھلی کرن آلے)", "mamulat.042": "(اے بے عیب ذات! سلامتی عطا کرن آلے)", "mamulat.043": "(اے اصلی کارساز)", "mamulat.044": "(اے نگہبان! مخلوق کی نگہبانی کرن آلے)", "mamulat.045": "(اے سارے جہاناں کے پروردگار)", "mamulat.046": "(اے سارے جہاناں کے اصلی پالن آلے)", "mamulat.047": "(اے سارے جہاناں کے اصلی ربّ)", "mamulat.048": "(اپنی رحمت کے صدقے! اے سب تے بڑھ کے رحم کرن آلے)", "mamulat.049": "اب چھوٹا ختم شریف پڑھو:", "mamulat.050": "(اے اللہ! میں تیرے تے مغفرت چاہوں ہوں)", "mamulat.051": "(اے اللہ! اے میرے ربّ! میں ہر گناہ تے معافی منگوں ہوں اور تیری طرف رجوع کروں ہوں)", "mamulat.052": "سورۃ الفاتحہ <span class=\"kk-c\">۷ بار</span>", "mamulat.053": "درودِ خالقیہ <span class=\"kk-c\">۱۱ بار</span>", "mamulat.054": "حضور نبی کریم ﷺ کے طفیل، سارے انبیاء کرام علیہم السلام، خلفائے راشدین، اہلِ بیت اطہار، صحابہ کرام رضی اللہ عنہم اور پیرانِ عظام نے ایصالِ ثواب کرو۔", "shajra.001": "شجرہ طریقت", "shajra.002": "چاروں سلسلیاں تے خلافت ہون کے باوجود ہمارے مرشداں نے سلسلہ عالیہ نقشبندیہ مجددیہ کی ترویج کری۔ اس لیے سلسلہ عالیہ کے بزرگاں کے ناں عام لوگاں کی جانکاری خاطر تبرک کے طور پہ پیش کیے جا رہے سیں۔", "shajra.003": "رحمۃ للعالمین، خاتم النبیین، سید المرسلین، حضرت محمد مصطفیٰ ﷺ<small>وصال 11ھ ۔ آرام گاہ گنبدِ خضریٰ</small>", "shajra.004": "یارِ غار و مزار، افضل البشر بعد الانبیاء بالتحقیق، سیدنا ابوبکر صدیقؓ<small>13ھ ۔ گنبدِ خضریٰ، مدینہ منورہ</small>", "shajra.005": "صحابیِ پاکباز، صاحبِ رسول اللہ ﷺ، حضرت سیدنا سلمان فارسیؓ<small>33ھ ۔ مدائن، عراق</small>", "shajra.006": "حضرت سیدنا امام قاسمؒ بن سیدنا محمدؒ بن سیدنا ابوبکر صدیقؓ<small>106ھ ۔ مدینہ منورہ</small>", "shajra.007": "امام الشریعت، ہادیِ طریقت حضرت سیدنا امام جعفر صادقؒ<small>148ھ ۔ جنت البقیع، قبۂ اہلِ بیت</small>", "shajra.008": "سلطان العارفین، غوثِ زمانی، حضرت شیخ بایزید بسطامیؒ<small>261ھ ۔ بسطام، ایران</small>", "shajra.009": "قطبِ ربانی، غوثِ زماں، خواجہ ابوالحسن خرقانیؒ<small>425ھ ۔ بسطام کے نیڑے خرقان، ایران</small>", "shajra.010": "عارفِ ربانی، قطبِ زمانی، حضرت شیخ ابوالقاسم گرگانیؒ<small>450ھ ۔ گرگان، ایران</small>", "shajra.011": "قطبِ صمدانی، حضرت شیخ بوعلی فارمدیؒ<small>477ھ ۔ طوس کے نیڑے فارمد، خراسان، ایران</small>", "shajra.012": "رئیس الطریقت، غوثِ زماں، امامِ ربانی، خواجہ یوسف ہمدانیؒ<small>535ھ ۔ مرو، ایران</small>", "shajra.013": "امام الطریقت خواجۂ جہاں خواجہ عبدالخالق غجدوانیؒ<small>575ھ ۔ بخارا کے نیڑے غجدوان، ازبکستان</small>", "shajra.014": "نورِ خدا، واقفِ معارفِ پیغمبری، خواجہ عارف ریوگریؒ<small>616ھ ۔ بخارا کے نیڑے ریوگر، ازبکستان</small>", "shajra.015": "خواجۂ خواجگاں، قطبِ جہاں، حضرت خواجہ محمود انجیر فغنویؒ<small>715ھ ۔ بخارا کے نیڑے انجیر فغنہ</small>", "shajra.016": "قطبِ زماں، مجددِ دوراں، حضرت خواجہ عزیزان علی رامیتنیؒ<small>718ھ ۔ خوارزم، ازبکستان</small>", "shajra.017": "بابِ الطریقت، آفتابِ حقیقت حضرت خواجہ بابا محمد سماسیؒ<small>755ھ ۔ بخارا کے نیڑے سماس</small>", "shajra.018": "عارفِ باکمال، صاحبِ وجد و حال، شمس الدین سید امیر کلالؒ<small>772ھ ۔ سوخار، بخارا</small>", "shajra.019": "امام الطریقت پیرِ پیراں خواجۂ خواجگاں خواجہ بہاؤالدین نقشبندؒ<small>791ھ ۔ قصرِ عارفاں، بخارا</small>", "shajra.020": "امام العارفین، قطبِ ارشاد حضرت خواجہ علاؤالدین عطارؒ<small>802ھ ۔ بخارا کے نیڑے چغانیاں</small>", "shajra.021": "شمس الہدایت، عارفِ ربانی، حضرت مولانا محمد یعقوب چرخیؒ<small>851ھ ۔ ماوراء النہر، تاجکستان</small>", "shajra.022": "مرشدِ عارف، خواجہ ناصرالدین عبیداللہ احرارؒ<small>895ھ ۔ سمرقند، ازبکستان</small>", "shajra.023": "فیضِ الٰہی، یکتائے زمانہ، حضرت مولانا خواجہ محمد زاہد وخشیؒ<small>936ھ ۔ وخش، بلخ</small>", "shajra.024": "مستِ عشق، حضرت مولانا خواجہ درویش محمد امکنگیؒ<small>970ھ ۔ ماوراء النہر</small>", "shajra.025": "مرکزِ دائرۂ قطبیت، دربانِ رسول مولانا شاہ محمد خواجگی امکنگیؒ<small>1008ھ ۔ امکنہ، بخارا</small>", "shajra.026": "فخرِ اسلام، نقشبندِ وقت، قطبِ زماں، خواجہ محمد باقی باللہ بیرنگؒ<small>1012ھ ۔ دہلی، انڈیا</small>", "shajra.027": "قیومِ اوّل، امامِ ربانی، مجدد الفِ ثانی، شیخ احمد فاروقی سرہندیؒ<small>1034ھ ۔ سرہند، انڈیا</small>", "shajra.028": "قیومِ ثانی، عروۃ الوثقیٰ خواجہ محمد معصومؒ<small>مجدد الفِ ثانیؒ کے شہزادے ۔ 1079ھ ۔ سرہند شریف</small>", "shajra.029": "قاطعِ بدعت، محتسبِ اُمت شیخ سیف الدینؒ<small>قیومِ ثانیؒ کے شہزادے ۔ 1096ھ ۔ سرہند شریف</small>", "shajra.030": "کشف الدجیٰ حضرت حافظ محمد محسنؒ<small>خواجہ محمد معصومؒ کے خلیفہ ۔ 1147ھ ۔ دہلی</small>", "shajra.031": "حضرت سید نور محمد بدایونیؒ<small>شیخ سیف الدینؒ کے خلیفہ ۔ 1135ھ ۔ دہلی</small>", "shajra.032": "قطبِ زماں خواجہ محمد عابد سنامیؒ<small>عبدالاحد سرہندی مجددی قادریؒ کے خلیفہ ۔ 1160ھ ۔ دہلی</small>", "shajra.033": "قیومِ زماں، قطبِ جہاں، شمس الدین حبیب اللہ مرزا مظہر جانِ جاناں شہیدؒ<small>1195ھ ۔ دہلی</small>", "shajra.034": "مجددِ دوراں، قیومِ زماں حضرت شاہ عبداللہ غلام علی دہلویؒ<small>1240ھ ۔ دہلی</small>", "shajra.035": "شیخ المشائخ، قیومِ زماں، حضرت شاہ ابوسعید فاروقی مجددیؒ<small>1250ھ ۔ دہلی</small>", "shajra.036": "شمس الاولیاء، حضرت مولانا بابا محمد شریف قندھاریؒ<small>1260ھ ۔ سرہند شریف</small>", "shajra.037": "سلطان الفقراء، حضرت حاجی محمود جالندھریؒ<small>1306ھ ۔ جالندھر شریف، انڈیا</small>", "shajra.038": "شمس العرفان خواجہ قادر بخشؒ<small>1306ھ ۔ کوٹ عبدالخالق جہانخیل، ضلع ہوشیارپور، انڈیا</small>", "shajra.039": "شمس الکونین خواجہ محمد عبدالخالق نقشبندیؒ<small>1931ء ۔ کوٹ عبدالخالق جہانخیل، ضلع ہوشیارپور، انڈیا</small>", "shajra.040": "شمس العارفین سائیں عبدالرزاق خالقی نقشبندیؒ<small>1982ء ۔ دیپالپور شریف، ضلع اوکاڑہ</small>", "shajra.041": "امام الذاکرین حضور سائیں محمد عظیم اللہ رزاقی نقشبندیؒ<small>2013ء ۔ عظیم نگر شریف، ضلع بہاولنگر</small>", "shajra.042": "شجرہ شریف (منظوم)", "shajra.043": "اس شجرہ طیبہ نے گھنے ادب تے باوضو پڑھن کی سخت تاکید سے۔ پڑھتے ویلے دل حاضر کر کے اپنے سبق کی طرف دھیان لاؤ، اپنی روحانی نسبت ٹھیک رکھ کے پیرانِ عظام تے فیض منگو۔ یو شجرہ طیبہ حضور سید عالم محمد مصطفیٰ ﷺ کا محبوب اور مقبول سے۔ نبی کریم رؤف رحیم ﷺ نے اپنے اس غلاماں کے غلام کی عاجزی قبول فرما کے خواب میں فقیر نے خبر دی سے کہ جو بندہ اس شجرہ طیبہ نے خلوصِ نیت تے پڑھے گا، اس کی کیسی بھی مشکل ہووے، ان شاء اللہ العزیز خواجگانِ نقشبندیہ کے طفیل ضرور حل ہووے گی۔ شجرہ شریف پڑھ کے حضور نبی کریم ﷺ کے وسیلے تے عرض گزارو اور محلل المشکلات، مسبب الاسباب، الٰہ العالمین تے مشکلاں کے حل خاطر دعا منگو۔", "shajra.044": "محمد مصطفیٰ ﷺ کے واسطے میری دستگیری کر", "shajra.045": "آل، اصحاب اور سارے انبیاء کے واسطے", "shajra.046": "یا الٰہی، اپنا درد میرے دل کا نصیب بنا دے", "shajra.047": "پاک صاف بوبکر صدیقِ اکبرؓ کے واسطے", "shajra.048": "اے خداوند، مجھے اپنے عشق میں کباب (جلا ہویا) بنا دے", "shajra.049": "حیا آلے صاحب سلمانؓ فارسی کے واسطے", "shajra.050": "اللہ کے سوا میرے سارے خیال دل تے دور ہو جاویں", "shajra.051": "ہدایت کے پیر امام قاسمؒ کے واسطے", "shajra.052": "یا الٰہی، کافر نفس کے شر تے بچا لے", "shajra.053": "پرہیزگاراں کے امام جعفر صادقؒ کے واسطے", "shajra.054": "یا الٰہی، مجھے شیطان کے مکر تے خبردار کر", "shajra.055": "راہ دکھان آلے بایزیدؒ کے واسطے", "shajra.056": "کوئی سانس بھی تیری یاد تے غافل نا ہون پاؤں", "shajra.057": "اولیاء کے تاج خواجہ بوالحسنؒ کے واسطے", "shajra.058": "اے ربّ، مجھے اپنی ذاتِ مطلق میں فنا کر دے", "shajra.059": "جھنڈے آلے شاہ بوالقاسمؒ کے واسطے", "shajra.060": "اے میرے ربّ، مجھے عین مطلق ذات تے غیر (جدا) نا کر", "shajra.061": "وفادار پیر و مرشد بو علیؒ کے واسطے", "shajra.062": "دل تے غیریت دور کر دے اور ہمیشہ کی حضوری دے", "shajra.063": "مقبول الدعا شاہ خواجہ یوسفؒ کے واسطے", "shajra.064": "اے ربّ، میری روح نقل تے نکل کے اصل میں شامل ہو جاوے", "shajra.065": "خطاواں کی سفارش کرن آلے عبدِ خالقؒ غجدوانی کے واسطے", "shajra.066": "نفس کی پچھان دے تاکہ میں اصل نے پچھان لوں", "shajra.067": "نورِ خدا محمد عارفؒ کے واسطے", "shajra.068": "عاشقاں کے دائرے نے معشوق تے ملا دے", "shajra.069": "غنا آلے خواجہ محمودؒ انجیر کے واسطے", "shajra.070": "یو غریب ہر دم تیرے وصل میں آرام پاوے", "shajra.071": "شاہ عزیزانؒ علیِ مرتضیٰ کے واسطے", "shajra.072": "رحمت کی نظر تے میری ساری خطاواں معاف کر دے", "shajra.073": "ادا آلے خواجہ بابا محمدؒ کے واسطے", "shajra.074": "یا الٰہی! مجھے امتِ احمد میں شمار کر لے", "shajra.075": "رضا آلے سیّد میر کلالؒ کے واسطے", "shajra.076": "مجھے شریعت اور طریقت پہ مضبوط رکھ", "shajra.077": "پیشوا شاہ بہاؤالدینؒ خواجہ کے واسطے", "shajra.078": "صراطِ مستقیم پہ ہمیشہ کی استقامت دے", "shajra.079": "روشنی آلے شاہ علاؤالدین عطارؒ کے واسطے", "shajra.080": "اے خداوند، مجھے پیر کی محبت عطا کر", "shajra.081": "بے ریا خواجہ یعقوبؒ چرخی کے واسطے", "shajra.082": "اے ربّ، مجھے پیرانِ کرام کی نظر میں مقبول کر", "shajra.083": "سخاوت آلے عبیداللہؒ احرار کے واسطے", "shajra.084": "میرے پیر کا عشق میرے دل میں وسا دے", "shajra.085": "برگزیدہ خواجہ زاہد محمدؒ کے واسطے", "shajra.086": "اے ربّ، پیراں کی نصیحت کا میرے ہر دم خیال رہوے", "shajra.087": "دلربا خواجہ درویش محمدؒ کے واسطے", "shajra.088": "اے خداوندِ کریم، میرے دل میں توکل دے", "shajra.089": "بلند شان آلے شاہ محمدؒ خواجگی کے واسطے", "shajra.090": "مجھے دنیا میں کدے غمگین نا کریو", "shajra.091": "بقا آلے محمد باقیؒ باللہ کے واسطے", "shajra.092": "میرے الٰہ، مجھے اپنے سوا کسے غیر کا محتاج نا کر", "shajra.093": "اندھیرے کے چاند (بدرالدجیٰ) مجدد صاحبؒ کے واسطے", "shajra.094": "جب نزع کا ویلا ہووے تو تیرا کلمہ زبان پہ ہووے", "shajra.095": "حضرتِ خواجہ معصومؒ کے واسطے", "shajra.096": "اس ویلے مجھے شیطان کے شر تے بچا لینا", "shajra.097": "عاشقِ مصطفیٰ شیخ سیف الدینؒ کے واسطے", "shajra.098": "اپنے فضل تے مجھے سکرات (موت کی سختی) تے چھٹکارا دیو", "shajra.099": "مخلوق کی پناہ گاہ محمد عابدؒ کے واسطے", "shajra.100": "الٰہی، تیرے فضل تے میری قبر روشن ہووے", "shajra.101": "اندھیرے دور کرن آلے شاہ محمد محسنؒ کے واسطے", "shajra.102": "نا قبر کی سختی ہووے اور نا فرشتے تے کوئی پریشانی", "shajra.103": "سوہنی صورت آلے سید نور محمدؒ کے واسطے", "shajra.104": "جس ویلے پل صراط پہ چلوں، گزرنا سوکھا ہووے", "shajra.105": "ہماری جان خواجہ مرزا جانِ جاناںؒ کے واسطے", "shajra.106": "اے ربّ، جس ویلے تیرا سورج تیز ہووے، امن دے", "shajra.107": "چڑھتے دن کے سورج غلام شاہ علیؒ کے واسطے", "shajra.108": "یا الٰہی، میزان میں نیکی کا پلڑا بھاری ہووے", "shajra.109": "برگزیدہ لوگاں کے رہنما بو سعیدؒ کے واسطے", "shajra.110": "اے جہان کے پیدا کرن آلے، اس ویلے کوئی خرابی نا ہووے", "shajra.111": "جان قربان کرن آلے محمد شریفؒ کے واسطے", "shajra.112": "اے خداوندِ علیم، میرا گزر عاشقاں میں ہووے", "shajra.113": "دل کھولن آلے حاجی محمود حافظؒ کے واسطے", "shajra.114": "اے ربّ، قیامت کے دن میں پیر کے سائے تھلے رہوں", "shajra.115": "ہما کے سائے جیسے خواجہ قادر بخشؒ کے واسطے", "shajra.116": "جدائی کے بخار تے دل میں درد سے، دوا کر دے", "shajra.117": "سڑے ہوئے دل کی دوا شمسِ عرفاںؒ کے واسطے", "shajra.118": "اے ربّ، محبوب کا وصل ہر دم میرا نصیب رہوے", "shajra.119": "ساری خواجگاں کے خواجہؒ، بلند تعریف آلے کے واسطے", "shajra.120": "میں غریب حال ہوں، اے ربّ رحم کی نظر کر", "shajra.121": "مصطفیٰ کی شان آلے محبوب مرشد کے واسطے", "shajra.122": "یعنی میری جان کے قبلہ، جہان کی پناہ آلے خواجہ", "shajra.123": "پیشوا شمس الکونین عبدالخالقؒ کے واسطے", "shajra.124": "میرے الٰہ، مجھے دین اور دنیا میں سرخرو کر", "shajra.125": "میرے پیارے سائیںؒ خواجہ پیشوا کے واسطے", "shajra.126": "زمانے کے غوث، جہان کے قطب، روشن ضمیر مرشد", "shajra.127": "اولیاء کے امام سائیں عبدالرزاقؒ کے واسطے", "shajra.128": "اے میرے ربِّ کریم، امید کا دامن بھر دے", "shajra.129": "ظلِ الٰہ کی صورت پیرِ کامل کے واسطے", "shajra.130": "میرا دل اور نظر ایمان کے نور تے سجا دے", "shajra.131": "نورِ خدا شاہ محمد عظیم اللہؒ کے واسطے", "shajra.132": "تیرے سوا کون سے؟ یو دل کا درد کس نے کہوں؟", "shajra.133": "ہر مراد خاطر تو ای حاجت روا سے", "shajra.134": "اے خدا، سینکڑاں مشکلاں کا سامنا سے", "shajra.135": "اپنی کبریائی کی شان کے واسطے سوکھا کر دے", "shajra.136": "بھلے میں برا ہوں پر تیرا ہوں، اے میرے عزّ و جل", "shajra.137": "مجھ بے سہارے نے تیری رحمت چاہیے", "shajra.138": "یا الٰہی، میری اولاد نے نصیب آلی کر", "shajra.139": "انبیاء اور اولیاء کی سخاوت اور عطا کے واسطے", "shajra.140": "دوستاں اور رشتے داراں نے محبت عطا کر", "shajra.141": "پیشوا نبی ﷺ کی آل اور حرمین کے واسطے", "shajra.142": "یا الٰہی، اپنے گنہگار کی دعا قبول کر لے", "shajra.143": "قیامت کے دن سفارش کرن آلے اس جناب کے واسطے", "azkar.001": "سنت آلے ذکر", "azkar.002": "نمازِ فجر اور مغرب کے پاچھے مسنون اذکار", "azkar.003": "<p class=\"kk-ar\" lang=\"ar\">وَسَبِّحُوْهُ بُكْرَةً وَّاَصِيْلًا</p><p class=\"kk-ur\">اور صبح شام اس کی تسبیح کریا کرو۔ (سورۃ احزاب: ۴۲)</p>", "azkar.004": "نوٹ: ہمارے امام ربانی مجدد الفِ ثانیؒ ہمیشہ صبح شام کے مسنون اذکار پڑھیا کرتے۔", "azkar.005": "(اللہ تعالیٰ کے سوا کوئی معبود نا، وہ اکیلا سے، اس کا کوئی شریک نا، اسی کی بادشاہی سے اور اسی کی تعریف سے اور وہ ہر چیز پہ قادر سے)۔", "azkar.006": "اے اللہ! مجھے جہنم تے نجات عطا فرما۔", "azkar.007": "مجھے اللہ کافی سے، اس کے سوا کوئی معبود نا، میں نے اسی پہ بھروسہ کریا اور وہ عرشِ عظیم کا رب سے۔", "azkar.008": "میں اس ذات پہ بھروسہ رکھوں ہوں جو زندہ سے، جسے موت نا۔", "azkar.009": "(صحیح مسلم)", "azkar.010": "۶۔ سورۃ الاخلاص اور معوذتین تسمیہ کے سات <span class=\"kk-c\">۳ بار</span>", "azkar.011": "(ابوداؤد)", "azkar.012": "میں اللہ تعالیٰ کے ربّ ہون پہ، اسلام کے دین ہون پہ اور ہمارے سردار حضرت محمد ﷺ کے نبی اور رسول ہون پہ راضی ہویا۔", "azkar.013": "(جامع ترمذی)", "azkar.014": "اللہ تعالیٰ کے ناں تے، جس کے ناں کی برکت تے زمین اور اسمان کی کوئی چیز نقصان نا پہنچا سکتی اور وہ سنن آلا، جانن آلا سے۔", "azkar.015": "(ترمذی)", "azkar.016": "اے اللہ! میرے بدن میں عافیت دے، اے اللہ! میرے سنن میں عافیت دے، اے اللہ! میری بصیرت میں عافیت دے، تیرے سوا کوئی معبود نا۔", "azkar.017": "(صحیح مسلم)", "azkar.018": "میں اللہ کے پورے اور کامل کلمیاں کے سات مخلوق کے شر تے پناہ لیوں ہوں۔", "azkar.019": "(صحیح مسلم)", "azkar.020": "پنج وقتی نماز کے پاچھے مسنون اذکار", "azkar.021": "<p class=\"kk-ar\" lang=\"ar\">فَاِذَا قَضَيْتُمُ الصَّلٰوةَ فَاذْكُرُوا اللّٰهَ قِيٰمًا وَّقُعُوْدًا وَّعَلٰى جُنُوْبِكُمْ</p><p class=\"kk-ur\">فیر جب تم نماز پڑھ لو تو کھڑے، بیٹھے اور کروٹاں پہ لیٹے اللہ کا ذکر کرو۔ (سورۃ النساء: ۱۰۳)</p>", "azkar.022": "<p class=\"kk-ar\" lang=\"ar\">فَسَبِّحْهُ وَاَدْبَارَ السُّجُوْدِ</p><p class=\"kk-ur\">اور اس کی تسبیح کرو اور نمازاں کے پاچھے بھی۔ (سورۃ ق: ۴۰)</p>", "azkar.023": "نوٹ: ہمارے امام ربانی مجدد الفِ ثانیؒ ہر نماز کے پاچھے مسنون دعاواں پڑھیا کرتے۔ کلمے پڑھتے ہوئے ترتیل، تجوید اور معنیاں کا خیال رکھو۔ ہر ورد تے پہلاں تسمیہ پڑھو۔", "azkar.024": "اے اللہ! تو ای سلامتی آلا سے اور تیری ای طرف تے سلامتی سے۔ تو گھنا بابرکت سے، اے بڈی شان اور عزت آلے۔", "azkar.025": "(صحیح مسلم)", "azkar.026": "۳۔ آیت الکرسی", "azkar.027": "(سلسلۃ الاحادیث الصحیحہ)", "azkar.028": "اے دلاں نے پھیرن آلے! میرے دل نے اپنے دین اور اپنی اطاعت پہ قائم رکھ۔", "azkar.029": "(ترمذی)", "azkar.030": "اے ہمارے ربّ! ہمارے دل ٹیڑھے نا کر اس کے پاچھے کہ تو نے ہمیں ہدایت دی، اور ہمیں اپنے کول تے رحمت عطا کر، بے شک تو گھنا عطا کرن آلا سے۔", "azkar.031": "(ابنِ ماجہ) (سورۃ آلِ عمران: ۸)", "azkar.032": "اے اللہ! اپنے ذکر، شکر اور اپنی سب تے چوکھی عبادت کرن میں میری مدد فرما۔", "azkar.033": "(ابوداؤد)", "azkar.034": "اے زندہ اور قائم رہن آلے! تیرے سوا کوئی معبود نا، میں سوال کروں ہوں کہ میرے دل نے ہمیشہ خاطر اپنے نورِ معرفت تے زندہ رکھ، اے بڈے جلال اور بزرگی آلے! تو پاک سے۔", "azkar.035": "(کنز العمال)", "azkar.036": "۸۔ تسبیحِ فاطمہ", "azkar.037": "سبحان اللہ ۳۳ بار، الحمد للہ ۳۳ بار، اللہ اکبر ۳۳ بار اور اک بار کلمہ توحید۔", "azkar.038": "(صحیح مسلم)", "azkar.039": "(ترمذی)", "azkar.040": "۱۰۔ کلمہ تمجید", "azkar.041": "۱۱۔ تینوں قل شریف", "azkar.042": "۱۱۔ سورۃ اخلاص <span class=\"kk-c\">۱۰ بار</span>", "azkar.043": "(مسند احمد)", "azkar.044": "چھوٹا ختمِ خواجگان", "azkar.045": "یو چھوٹا ختمِ خواجگان نمازِ فجر اور نمازِ عصر کے پاچھے پڑھن کا معمول بناؤ۔", "azkar.046": "۱۔ اَستغفر اللہ <span class=\"kk-c\">۲۶ بار</span>", "azkar.047": "۲۔ سورۃ الفاتحہ <span class=\"kk-c\">۷ بار</span>", "azkar.048": "۳۔ درود شریف <span class=\"kk-c\">۱۱ بار</span>", "azkar.049": "نماز کی وادھو مسنون دعاواں", "azkar.050": "نوٹ: عروۃ الوثقیٰ خواجہ محمد معصوم سرہندیؒ فرماویں سیں کہ ثناء کے علاوہ نماز شروع کرن کی ماثور دعاواں، اور اسی طرح تسبیحات کے علاوہ رکوع و سجود کی دعاواں اور قومہ و جلسہ کی دعاواں جو احادیثِ مبارکہ میں آئی سیں، انہاں نے تہجد اور دوجے نفلاں میں پڑھو تو یو گھنا چوکھا سے، اور آخری قعدے میں درود شریف کے پاچھے قرآنی دعاواں یا ماثور و مسنون دعاواں پڑھو۔ جیسا کہ صحیح بخاری میں حدیث شریف سے: فیر وہ دعا منگے جو اسے پسند ہووے۔ (اذکارِ نبویہ)", "azkar.051": "اللہ سب تے بڈا سے، گھنا بڈا، اور اللہ خاطر گھنی ساری حمد سے اور میں صبح شام اللہ کی تسبیح کروں ہوں۔ حضرت جبیر بن مطعمؓ بیان فرماویں سیں کہ انہاں نے نبی ﷺ نے اک نماز پڑھتے دیکھیا، آپ ﷺ نے نماز کے شروع میں یو کلمے پڑھے۔", "azkar.052": "(سنن ابوداؤد)", "azkar.053": "گھنا ای پاکیزہ، انتہائی مقدس، فرشتیاں اور روح کا ربّ۔ یو کلمے رکوع اور سجدے میں پڑھنا سنت سے۔ نبی ﷺ نے فرمایا: بندہ اپنے ربّ کے سب تے نیڑے سجدے میں ہووے سے، اس لیے سجدے میں ودھ تے ودھ دعا کریا کرو۔", "azkar.054": "(صحیح مسلم)", "azkar.055": "نوٹ: ہمارے امامِ ربانی مجدد الفِ ثانیؒ ویہلے ویلے رکوع اور سجدے میں پانچ، سات، نو یا گیارہ بار تسبیحات پڑھیا کرتے۔ اور فرمایا کرتے کہ شرم آوے سے کہ طاقت ہوتے ہوئے اور ویہلے ہوتے ہوئے بھی بس تین تسبیحات پہ ای گزارا کریا جاوے۔ (حضرات القدس)", "azkar.056": "اے میرے ربّ! ساری تعریف تیرے خاطر سے، ایسی تعریف جو گھنی ساری، پاکیزہ اور برکت آلی سے۔ اے ہمارے ربّ! جیسی تجھے پسند ہووے، جس تے تو راضی ہو جاوے۔ قومہ، یعنی رکوع تے سر اٹھان کے پاچھے، یو کلمے خاص کر نفل نماز میں پڑھنا سنت سے۔", "azkar.057": "(بخاری)", "azkar.058": "اے اللہ! میری بخشش فرما، میرے پہ رحم فرما، مجھے ہدایت دے، مجھے رزق دے، مجھے بلند درجہ عطا فرما، میری بگڑی سنوار دے اور مجھے عافیت عطا فرما۔ دونوں سجدیاں کے وچکار جلسے میں، خاص کر نفل نماز میں، ان کلمیاں نے پڑھنا سنت سے۔", "azkar.059": "(سنن ابوداؤد، ترمذی)", "azkar.060": "آرام (سون) کے ویلے کے مسنون اذکار", "azkar.061": "سورۃ الزمر میں ارشادِ الٰہی سے: اللہ تعالیٰ جاناں نے ان کی موت کے ویلے وفات دیوے سے اور ان جاناں نے بھی جن کی موت نا آئی، ان کے سون کے ویلے۔ (۴۲)", "azkar.062": "<p class=\"kk-ar\" lang=\"ar\">وَسَبِّحْهُ لَيْلًا طَوِيْلًا</p><p class=\"kk-ur\">سورۃ الدہر میں ارشاد ہویا: اور لمبی رات میں اس کی تسبیح کرو۔ (۲۶)</p>", "azkar.063": "نبی کریم ﷺ نے فرمایا: دنیا میں کچھ لوگ نرم بستراں پہ اللہ تعالیٰ نے یاد کریں سیں، اللہ تعالیٰ انہاں نے اعلیٰ جنّت میں داخل فرماوے گا۔ (مصنف ابی یوسف)۔ جو بندہ بستر پہ لیٹے یا کسے مجلس میں بیٹھے اور اس میں اللہ تعالیٰ کا ذکر نا کرے تو قیامت کے دن یو اس خاطر حسرت ہووے گی۔ (ابوداؤد)", "azkar.064": "نوٹ: ہمارے امامِ ربانیؒ سوتے ویلے سورتاں، آیتاں، تسبیحات اور ماثورہ دعاواں پڑھیا کرتے۔", "azkar.065": "نبی کریم ﷺ نے سیدنا علی المرتضیٰؓ تے فرمایا کہ اے علیؓ! پانچ کام کر کے سویا کرو:", "azkar.066": "۱۔ سورۃ الفاتحہ <span class=\"kk-c\">۴ بار</span>", "azkar.067": "چار بار پڑھ کے سویا کرو، یو چار ہزار دینار صدقہ کرن کے برابر سے۔", "azkar.068": "۲۔ سورۃ اخلاص <span class=\"kk-c\">۳ بار</span>", "azkar.069": "تین بار پڑھ کے سویا کرو۔ یو اک بار قرآن مجید پڑھن کے برابر سے۔", "azkar.070": "دس بار پڑھ کے سویا کرو۔ اس کا اجر دو لڑن آلیاں میں صلح کران کے برابر سے۔", "azkar.071": "۴۔ درود شریف <span class=\"kk-c\">۱۰ بار</span>", "azkar.072": "دس بار پڑھ کے سویا کرو۔ یو جنت کی قیمت ادا کرن کے برابر سے۔", "azkar.073": "۵۔ کلمہ تمجید <span class=\"kk-c\">۴ بار</span>", "azkar.074": "چار بار پڑھ کے سویا کرو۔ یو اک حج کرن کے برابر سے۔", "azkar.075": "۶۔ سورۃ الکافرون <span class=\"kk-c\">اک بار</span>", "azkar.076": "حضرت نوفلؓ فرماویں سیں کہ نبی کریم ﷺ نے مجھے ارشاد فرمایا: سورۃ الکافرون پڑھ کے سویا کرو کیونکہ یو شرک تے براءت سے۔", "azkar.077": "(ابوداؤد)", "azkar.078": "۷۔ تینوں قل شریف <span class=\"kk-c\">۳ بار</span>", "azkar.079": "اُمّ المومنین عائشہ صدیقہؓ فرماویں سیں کہ جب نبی کریم ﷺ آرام فرمان خاطر بستر پہ تشریف لاتے تو دونوں ہاتھ جوڑ کے سورۃ اخلاص اور فلق و ناس پڑھ کے دم کرتے اور بدنِ اقدس کے جس حصے تئیں ہاتھ پہنچتے اتھے تئیں ہاتھ پھیرتے، اور ہاتھ پھیرن کی شروعات سر اور چہرے تے کرتے، اور یو عمل تین بار کریا کرتے۔", "azkar.080": "(صحیح بخاری)", "azkar.081": "نبی ﷺ نے فرمایا: جو بندہ یو استغفار بستر پہ لیٹتے ویلے تین بار پڑھ لیوے اس کے گناہ بخش دیے جاویں سیں، بھلے سمندر کی جھاگ کے برابر ہوویں، بھلے درختاں کے پتیاں کے برابر ہوویں، بھلے ٹیلیاں کی ریت کے ذرّیاں کے برابر ہوویں، بھلے دنیا کے دناں کے برابر ہوویں۔", "azkar.082": "(ترمذی)", "azkar.083": "۹۔ آیت الکرسی", "azkar.084": "نبی ﷺ نے فرمایا: جو بندہ سوتے ویلے آیت الکرسی پڑھے تو اک فرشتہ اس کی حفاظت خاطر مقرر کر دیا جاوے سے اور صبح تئیں شیطان اس کے کول نا آتا۔ (بخاری) جو بستر پہ لیٹ کے اسے پڑھے گا تو اللہ تعالیٰ اس کے آلے دوالے کے کئی گھراں کی حفاظت فرماوے سے۔", "azkar.085": "۱۰۔ بسم اللہ شریف <span class=\"kk-c\">۲۱ بار</span>", "azkar.086": "نبی کریم ﷺ نے ارشاد فرمایا کہ جو بندہ سون تے پہلاں ۲۱ بار تسمیہ پڑھے تو وہ چوری، شیطانی اثراں اور اچانک موت تے محفوظ رہوے گا۔", "azkar.087": "۱۱۔ تسبیحِ فاطمہ", "azkar.088": "(متفق علیہ)", "azkar.089": "۱۲۔ دعائے نوم", "azkar.090": "یا اللہ! میں تیرے ای ناں تے مروں ہوں اور تیرے ای ناں تے جیوں ہوں۔", "azkar.091": "(متفق علیہ)", "azkar.092": "۱۳۔ سورۃ البقرہ کی آخری دو آیتاں", "azkar.093": "شبِ جمعہ اور جمعے کے دن کے مسنون اذکار", "azkar.094": "نوٹ: ہمارے امامِ ربانی مجدد الفِ ثانیؒ گھنا سارا نبی کریم ﷺ کی بارگاہ میں قسم قسم کے درود شریف بھیجیا کرتے، خاص کر شبِ جمعہ اور جمعے کے دن، پیر کی رات اور پیر کے دن۔ آخری زمانے میں شبِ جمعہ نے مریداں کے سات حلقۂ ذکر کے پاچھے ہزار بار درود شریف بھیجیا کرتے۔", "azkar.095": "۱۔ شبِ جمعہ کا درود شریف <span class=\"kk-c\">ہزار بار</span>", "azkar.096": "۲۔ جمعے کے پاچھے درود شریف <span class=\"kk-c\">ہزار بار</span>", "azkar.097": "شیخ عبدالقادر جیلانیؒ نے غنیۃ الطالبین میں جمعے کے دن یو درود شریف پڑھن کی تلقین فرمائی سے۔", "azkar.098": "۳۔ نمازِ عصر کے پاچھے درود شریف <span class=\"kk-c\">۸۰ بار</span>", "azkar.099": "سیدنا ابوہریرہؓ تے روایت ارشادِ نبوی ﷺ سے: جس نے جمعے کے دن نمازِ عصر پڑھ کے اسی جگہ بیٹھے بیٹھے ۸۰ بار یو درودِ پاک پڑھیا تو اس کے ۸۰ سال کے گناہ بخش دیے جاویں گے اور اس کے نامۂ اعمال میں ۸۰ سال کی عبادت کا ثواب لکھیا جاوے سے۔", "azkar.100": "(دیلمی، امام سخاوی)", "azkar.101": "۴۔ کیمیائے مشائخ", "azkar.102": "شیخ عبدالحق محدث دہلویؒ نے اگلے پچھلے گناہاں کی مغفرت خاطر اک آزمایا ہویا وظیفہ «کیمیائے مشائخ» لکھیا سے کہ نمازِ جمعہ کا سلام پھیرن کے پاچھے تشہد کی حالت میں سورۃ فاتحہ اور تینوں قل شریف تسمیہ کے سات سات سات بار پڑھو۔ حدیث شریف میں سے کہ ان سورتاں کا پڑھنا اس جمعے تے اگلے جمعے تئیں شیطان تے پناہ دیوے گا۔", "azkar.103": "(کیمیائے سعادت)", "azkar.104": "نوٹ: امامِ ربانیؒ نمازِ جمعہ کے پاچھے سورۃ فاتحہ اور تینوں قل تسمیہ کے سات سات سات بار پڑھیا کرتے۔", "azkar.105": "<p class=\"kk-ar\" lang=\"ar\">فَاِذَا قُضِيَتِ الصَّلٰوةُ فَانْتَشِرُوْا فِي الْاَرْضِ وَابْتَغُوْا مِنْ فَضْلِ اللّٰهِ</p><p class=\"kk-ur\">فیر جب نماز ہو چکے تو زمین میں پھیل جاؤ اور اللہ کا فضل ٹوہو۔ (سورۃ جمعہ: ۱۰)</p>", "azkar.106": "حضرت انسؓ فرماویں سیں: خرید و فروخت اور دنیا کمانا اس آیت کا مطلب نا، بلکہ علم ٹوہنا، بھائیاں تے ملن جانا، بیماراں کی عیادت، جنازے کے سات جانا اور جو بھی ایسے نیک کام ہوویں وہ اس آیت تے مراد سیں۔ کیونکہ اللہ تعالیٰ نے سورۃ جمعہ میں اگے ارشاد فرمایا سے:", "azkar.107": "<p class=\"kk-ar\" lang=\"ar\">وَاذْكُرُوا اللّٰهَ كَثِيْرًا لَّعَلَّكُمْ تُفْلِحُوْنَ</p><p class=\"kk-ur\">اور اللہ کا ذکر گھنا کرو تاکہ تم فلاح پاؤ۔</p>", "programs.001": "سال کے پروگرام", "atiyat.001": "عطیات", "atiyat.002": "تحریک کی دینی اور اصلاحی خدمتاں وچ تعاون کرن آلیاں تائیں — اللہ قبول فرماوے۔", "rabta.001": "رابطہ", "about.001": "ایپ کے بارے میں", "kutub.020": "خوفِ خدا اور عشقِ مصطفیٰ ﷺ", "kutub.021": "<span>مؤلف:</span> بانی اور قائد تحریک اتباعِ سنت پاکستان، پیرِ طریقت، شیرِ مجدد بدرالہدیٰ کرامت علی رزّاقی عظیمی نقشبندی <span class=\"lat\">(M.A, L.L.B)</span>", "kutub.022": "<span>معاونت:</span> انجینئر شعیب عالم عظیمی مجددی (ایم اے علومِ اسلامیہ)، <span class=\"lat\">HOD</span> الیکٹریکل ٹریڈ، گورنمنٹ ٹیکنیکل ٹریننگ انسٹی ٹیوٹ لودھراں", "kutub.023": "صفحے: <span class=\"lat\">128</span>  • چھپائی: دسمبر <span class=\"lat\">2019</span> (دوسرا ایڈیشن)"};
